  test("static handler Cache-Control values MUST equal exactly the documented 3-tier closed set {public max-age=31536000, public max-age=0 must-revalidate, no-store} per StaticAssetsHandler.scala lines 94-96 + the applySecurityHeaders default for 404 -- the CACHE-CONTROL-TIER pin consolidates the per-tier individual tests into a single closed-set assertion catching 4th-tier-introduction + per-path-mapping-swap refactors") {
    withStaticSite { staticDir =>
      Files.createDirectories(staticDir.resolve("vendor"))
      Files.writeString(staticDir.resolve("vendor").resolve("lib.js"), "x", StandardCharsets.UTF_8)
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // Hit all 3 documented tier paths
        val vendorResp = get(s"$baseUri/vendor/lib.js")
        assertEquals(vendorResp.statusCode(), 200,
          clue = "vendor asset MUST return 200 to inspect its Cache-Control")
        val vendorCacheControl = headerValue(vendorResp, "Cache-Control")
          .getOrElse(fail("vendor response MUST have Cache-Control header"))

        val htmlResp = get(s"$baseUri/index.html")
        assertEquals(htmlResp.statusCode(), 200,
          clue = "index.html MUST return 200")
        val htmlCacheControl = headerValue(htmlResp, "Cache-Control")
          .getOrElse(fail("HTML response MUST have Cache-Control header"))

        val notFoundResp = get(s"$baseUri/missing-file.html")
        assertEquals(notFoundResp.statusCode(), 404,
          clue = "non-existent file MUST return 404")
        val notFoundCacheControl = headerValue(notFoundResp, "Cache-Control")
          .getOrElse(fail("404 response MUST have Cache-Control header"))

        // (i) Per-tier VALUE assertions (mirror existing
        // individual tests for defense-in-depth)
        assertEquals(vendorCacheControl, "public, max-age=31536000",
          clue = s"vendor asset Cache-Control MUST equal `public, max-age=31536000` per StaticAssetsHandler.scala line 95's documented 1-year cache for vendor assets (these are immutable third-party libraries that don't change between releases); a refactor changing the value would silently affect cache hit rates for ALL vendor assets; got: $vendorCacheControl")
        assertEquals(htmlCacheControl, "public, max-age=0, must-revalidate",
          clue = s"HTML asset Cache-Control MUST equal `public, max-age=0, must-revalidate` per StaticAssetsHandler.scala line 96's documented HTML/CSS/JS cache policy (allow browser cache but force revalidation per request); a refactor changing the value would silently affect HTML page caching behavior; got: $htmlCacheControl")
        assertEquals(notFoundCacheControl, "no-store",
          clue = s"404 Cache-Control MUST equal `no-store` per the applySecurityHeaders default (the static handler's 200 path overrides Cache-Control but the 404 path uses the default); got: $notFoundCacheControl")

        // (ii) CLOSED-SET assertion: the static handler
        // emits EXACTLY 3 distinct Cache-Control values
        // across these paths (the CORE TIER closure)
        val cacheControlValues = Set(vendorCacheControl, htmlCacheControl, notFoundCacheControl)
        val expectedTiers = Set(
          "public, max-age=31536000",
          "public, max-age=0, must-revalidate",
          "no-store"
        )
        assertEquals(cacheControlValues, expectedTiers,
          clue = s"static handler Cache-Control values across the 3 documented path categories MUST equal exactly the closed set {`public, max-age=31536000`, `public, max-age=0, must-revalidate`, `no-store`} per StaticAssetsHandler.scala lines 94-96 + the applySecurityHeaders default for 404 -- a refactor introducing a 4th tier (e.g. `private, max-age=300` for user-specific assets) would silently widen the closed set; a refactor swapping the per-path mapping (e.g. /vendor/* gets no-store, HTML gets 1-year cache) would silently break operator-visible cache behavior + dashboard expectations; got: ${cacheControlValues.toVector.sorted.mkString(", ")}, expected: ${expectedTiers.toVector.sorted.mkString(", ")}")
        assertEquals(cacheControlValues.size, 3,
          clue = s"static handler MUST emit 3 DISTINCT Cache-Control values across the 3 documented path categories -- if 2 or more categories collapse to the same value, the documented tier distinction has been silently lost; got distinct count: ${cacheControlValues.size}")

        // (iii) CROSS-HANDLER CONSISTENCY: static 404
        // Cache-Control EQUALS JsonHandler Cache-Control
        // (both inherit the applySecurityHeaders default)
        val jsonResp = get(s"$baseUri/api/health")
        assertEquals(notFoundCacheControl, headerValue(jsonResp, "Cache-Control").getOrElse(""),
          clue = s"static 404 Cache-Control MUST EQUAL JsonHandler Cache-Control -- both inherit the applySecurityHeaders default at WebResponses.scala line 115 (the static handler's 200 path overrides for vendor + HTML, but the 404 path doesn't override, so it gets the default no-store matching JsonHandler); got static-404=$notFoundCacheControl, json=${headerValue(jsonResp, "Cache-Control").getOrElse("")}")

        // (iv) BOUNDARY assertion: NONE of the static-200
        // tiers (vendor + HTML) match the applySecurityHeaders
        // default no-store -- they're explicitly overridden
        assertNotEquals(vendorCacheControl, "no-store",
          clue = "vendor Cache-Control MUST NOT be no-store -- the static handler explicitly overrides for /vendor/* assets to enable aggressive caching; a refactor dropping the override would silently force browsers to re-fetch large vendor libraries on every request")
        assertNotEquals(htmlCacheControl, "no-store",
          clue = "HTML Cache-Control MUST NOT be no-store -- the static handler explicitly overrides for HTML to allow caching with revalidation; a refactor dropping the override would silently force browsers to re-fetch HTML on every navigation, degrading performance significantly")
      }
    }
  }

  // Pin the documented STATIC-HANDLER ETAG FORMAT
  // contract at StaticAssetsHandler.scala line 93's
  // `etag = s"""W/"$size-$lastModified${if
  // wouldCompressIfGet then "-gz" else ""}""""` -- the
  // ETAG-FORMAT pin verifies the documented weak-ETag
  // structure (W/ prefix + double-quote-wrapped + size-
  // lastModified[-gz] body) per RFC 7232 sec 2.3.1 weak
  // ETag semantics + the documented gzip-variant suffix
  // for conservative caches that key on ETag without
  // Vary; existing tests at line 9249 + line 10248
  // verify ETag PRESENCE on vendor responses but not the
  // FORMAT structure; FORTY-FIFTH per-emission-site
  // SHAPE pin overall; the ETag format is OPERATIONALLY
  // CRITICAL because: (a) browsers + caching proxies
  // use the ETag for If-None-Match conditional GETs to
  // skip body bytes on unchanged resources -- a refactor
  // breaking the format would silently cause revalidation
  // failures, forcing full re-downloads even when the
  // resource hasn't changed, (b) the W/ weak-prefix
  // indicates the ETag is content-equivalence-only (NOT
  // byte-for-byte) -- a refactor changing to strong
  // ETags would silently reject conditional requests
  // that should have succeeded (different gzip versions
  // would mismatch), (c) the -gz suffix variant is the
  // documented defense against the cache-poisoning
  // attack where a conservative cache (keying on ETag
  // without Vary: Accept-Encoding) might serve the
  // gzipped body to an uncompressed-Accept-Encoding
  // client -- a refactor dropping the suffix would
  // silently reintroduce the cache-poisoning vector;
  // per-format regression vectors uniquely caught: (i)
  // refactor dropping the W/ weak prefix would silently
  // upgrade to strong ETags + break gzip-vs-uncompressed
  // revalidation, (ii) refactor changing the format
  // (e.g. dropping the size-lastModified components OR
  // adding new components without updating callers)
  // would silently break If-None-Match matching, (iii)
  // refactor dropping the -gz suffix would silently
  // reintroduce the gzip-variant cache-poisoning vector;
  // test approach: GET /index.html WITHOUT Accept-
  // Encoding: gzip → verify ETag has documented
  // structure but NO -gz suffix; GET /index.html WITH
  // Accept-Encoding: gzip → verify ETag has -gz suffix;
  // assert the two ETags differ (the documented gzip-
  // variant invariant).
  test("static handler ETag MUST follow the documented `W/\"<size>-<lastModified>[-gz]\"` weak-ETag format per StaticAssetsHandler.scala line 93's emission with the documented gzip-variant suffix for cache-keying disambiguation -- the ETAG-FORMAT pin closes the documented RFC 7232 sec 2.3.1 weak-ETag contract + the documented defense against gzip-variant cache poisoning") {
    withStaticSite { staticDir =>
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // GET index.html WITHOUT Accept-Encoding: gzip
        val plainResp = get(s"$baseUri/index.html")
        assertEquals(plainResp.statusCode(), 200,
          clue = "GET /index.html MUST return 200")
        val plainEtag = headerValue(plainResp, "ETag")
          .getOrElse(fail("static 200 response MUST include ETag header per StaticAssetsHandler.scala line 98's emission"))

        // (i) ETag starts with `W/` (weak ETag per RFC 7232
        // sec 2.3.1)
        assert(plainEtag.startsWith("W/"),
          clue = s"static handler ETag MUST start with `W/` (weak ETag prefix per RFC 7232 sec 2.3.1) -- a refactor dropping the W/ prefix would silently upgrade to strong ETags, breaking gzip-vs-uncompressed revalidation (the weak ETag indicates content-equivalence, allowing different byte-for-byte representations to share an ETag); got: $plainEtag")

        // (ii) ETag is double-quote wrapped (after the W/)
        val plainBody = plainEtag.stripPrefix("W/")
        assert(plainBody.startsWith("\"") && plainBody.endsWith("\""),
          clue = s"static handler ETag body (after W/) MUST be double-quote wrapped per RFC 7232 sec 2.3 (the etag-value production requires DQUOTE); a refactor dropping the quotes would silently break clients that parse the ETag value (most HTTP clients enforce the quote contract); got: $plainEtag")

        // (iii) ETag plain body does NOT end with -gz
        // (no gzip suffix on the uncompressed variant)
        val plainEtagInside = plainBody.stripPrefix("\"").stripSuffix("\"")
        assert(!plainEtagInside.endsWith("-gz"),
          clue = s"static handler ETag (uncompressed variant) MUST NOT end with `-gz` per the documented gzip-variant disambiguation -- the `-gz` suffix is the documented marker for the gzipped representation; got: $plainEtag")

        // (iv) GET with Accept-Encoding: gzip → ETag SHOULD
        // have -gz suffix
        val gzipResp = get(s"$baseUri/index.html", Map("Accept-Encoding" -> "gzip"))
        assertEquals(gzipResp.statusCode(), 200,
          clue = "GET with Accept-Encoding: gzip MUST return 200")
        val gzipEtag = headerValue(gzipResp, "ETag")
          .getOrElse(fail("gzipped response MUST include ETag header"))

        // (v) gzip variant ETag also starts with W/ + quoted
        assert(gzipEtag.startsWith("W/"),
          clue = s"gzip-variant ETag MUST also start with W/ (weak ETag); got: $gzipEtag")

        // (vi) gzip variant ETag ends with -gz before the
        // closing quote (the documented gzip-variant
        // disambiguation per RFC 7232 + the cache-poisoning
        // defense for conservative caches)
        val gzipEtagInside = gzipEtag.stripPrefix("W/").stripPrefix("\"").stripSuffix("\"")
        assert(gzipEtagInside.endsWith("-gz"),
          clue = s"gzipped static response ETag MUST end with `-gz` (before closing quote) per StaticAssetsHandler.scala line 93's gzip-conditional template -- the documented gzip-variant disambiguation per RFC 7232 sec 2.3.1 protects against the cache-poisoning attack where conservative caches keying on ETag without Vary: Accept-Encoding might serve the gzipped body to an uncompressed-Accept-Encoding client; got: $gzipEtag")

        // (vii) the gzip ETag MUST differ from the plain
        // ETag (the gzip-variant invariant -- otherwise
        // conditional requests would match across variants)
        assertNotEquals(plainEtag, gzipEtag,
          clue = s"gzipped ETag MUST differ from plain ETag per the documented gzip-variant disambiguation -- if they matched, a conservative cache (keying on ETag without Vary) could serve the wrong variant; got plain=$plainEtag, gzip=$gzipEtag")

        // (viii) the gzip ETag MUST be the plain ETag with
        // `-gz` inserted before the closing quote -- the
        // structural relationship between the two variants
        // is documented (same size + lastModified, just
        // with the suffix)
        val expectedGzipEtag = plainEtag.stripSuffix("\"") + "-gz\""
        assertEquals(gzipEtag, expectedGzipEtag,
          clue = s"gzipped ETag MUST equal the plain ETag with `-gz` inserted before the closing quote per the documented structural relationship (same size + lastModified components, just with the gzip-variant suffix); got gzip=$gzipEtag, expected=$expectedGzipEtag")
      }
    }
  }

  // Pin the documented If-None-Match W/-PREFIX NORMALIZATION
  // contract at StaticAssetsHandler.scala lines 122-129 --
  // the WEAK-COMPARISON pin verifies the documented RFC 7232
  // sec 2.3.2 weak-comparison semantics where the server
  // accepts a CDN-stripped bare opaque-tag (without `W/`
  // prefix) as equivalent to the server's emitted weak
  // ETag (with `W/` prefix); the documented inline comment
  // at lines 117-124 explains the CDN-resilience rationale:
  // a misbehaving CDN/proxy could strip the W/ in transit,
  // and direct string equality would silently fail
  // revalidation forcing a full-body re-fetch on every
  // poll -- the line 128 stripWeakPrefix normalization is
  // the documented defense; FORTY-SIXTH per-emission-site
  // SHAPE pin overall; the W/-prefix normalization is
  // OPERATIONALLY CRITICAL because: (a) the documented
  // CDN-resilience design ensures revalidation works
  // correctly even when conservative caching proxies strip
  // the W/ marker -- a refactor removing the normalization
  // would silently disable revalidation through such
  // proxies, forcing operators to either disable
  // the proxy OR pay the full-body-re-fetch cost on every
  // page load, (b) RFC 7232 sec 2.3.2 MANDATES weak
  // comparison for If-None-Match -- a refactor switching
  // to direct equality would silently violate the RFC + the
  // documented sec 2.3.2 quote in the inline comment;
  // per-format regression vectors uniquely caught (NOT
  // caught by 4a49db1 which pins the EMITTED ETag format
  // OR the existing line 10044 test that uses the verbatim
  // server-emitted form): (i) refactor dropping the line
  // 128 stripWeakPrefix call on the server-emitted ETag
  // would silently break revalidation for clients that
  // echo back the bare form, (ii) refactor dropping the
  // line 129 stripWeakPrefix call on the client-submitted
  // ETag would silently break revalidation for clients
  // that submit the bare form (the documented CDN-strip
  // scenario), (iii) refactor switching from weak
  // comparison to strong comparison would silently break
  // ALL revalidation across the gzip/uncompressed variant
  // boundary AND break the CDN-resilience contract; test
  // approach: GET /index.html → 200 with ETag `W/"..."`,
  // strip the W/ prefix to get the bare form, GET
  // /index.html with If-None-Match: <bare-form> → 304
  // (the documented W/-normalization match).
  test("static handler If-None-Match WEAK COMPARISON accepts the CDN-stripped bare opaque-tag (without `W/` prefix) as equivalent to the server's weak ETag per StaticAssetsHandler.scala lines 122-129's documented RFC 7232 sec 2.3.2 weak-comparison + CDN-resilience contract -- complements 4a49db1's emitted-ETag format pin + the existing line 10044 verbatim-match test by pinning the W/-stripped form match") {
    withStaticSite { staticDir =>
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // Get the server's emitted ETag (W/-prefixed)
        val firstResp = get(s"$baseUri/index.html")
        assertEquals(firstResp.statusCode(), 200,
          clue = "first GET MUST return 200")
        val emittedEtag = headerValue(firstResp, "ETag")
          .getOrElse(fail("server MUST emit ETag on the first response"))
        assert(emittedEtag.startsWith("W/"),
          clue = s"server-emitted ETag MUST start with W/ (the weak-ETag prefix per 4a49db1's format pin); got: $emittedEtag")

        // Strip the W/ prefix to simulate a CDN that strips
        // the marker in transit (the documented scenario)
        val cdnStrippedEtag = emittedEtag.stripPrefix("W/")
        assert(!cdnStrippedEtag.startsWith("W/"),
          clue = s"sanity check: the stripped ETag should NOT start with W/; got: $cdnStrippedEtag")
        assert(cdnStrippedEtag.startsWith("\"") && cdnStrippedEtag.endsWith("\""),
          clue = s"the stripped ETag should still be quoted (just without the W/ prefix); got: $cdnStrippedEtag")

        // (i) GET with If-None-Match: <CDN-stripped-bare-form>
        // → 304 (the documented W/-normalization match)
        val cdnRevalidate = get(s"$baseUri/index.html", Map("If-None-Match" -> cdnStrippedEtag))
        assertEquals(cdnRevalidate.statusCode(), 304,
          clue = s"GET with If-None-Match: <CDN-stripped-bare-form> MUST return 304 Not Modified per StaticAssetsHandler.scala lines 128-129's stripWeakPrefix normalization -- the documented defense against CDN-strip behavior; if this assertion fails, the normalization has been silently broken + clients behind a stripping CDN would force full-body re-fetches on every poll; got status: ${cdnRevalidate.statusCode()}, body length: ${cdnRevalidate.body().length}")

        // (ii) the 304 response MUST be body-less per RFC
        // 7232 sec 4.1 (304 MUST NOT include a message-body)
        assertEquals(cdnRevalidate.body(), "",
          clue = s"304 response MUST be body-less per RFC 7232 sec 4.1; got body length: ${cdnRevalidate.body().length}")

        // (iii) the 304 response MUST include the ETag
        // header per RFC 7232 sec 4.1 (304 SHOULD generate
        // the same headers that would have been sent on a
        // 200 OK)
        assertEquals(headerValue(cdnRevalidate, "ETag"), Some(emittedEtag),
          clue = s"304 response MUST include the ETag header (matching the original W/-prefixed emitted ETag, NOT the CDN-stripped form) per RFC 7232 sec 4.1; got: ${headerValue(cdnRevalidate, "ETag")}")

        // (iv) SYMMETRIC CHECK: GET with If-None-Match:
        // <verbatim-W/-prefixed-form> ALSO returns 304 (the
        // existing line 10044 test path -- verify both
        // forms work via the normalization)
        val verbatimRevalidate = get(s"$baseUri/index.html", Map("If-None-Match" -> emittedEtag))
        assertEquals(verbatimRevalidate.statusCode(), 304,
          clue = "verbatim W/-prefixed form MUST ALSO return 304 (both forms work via the normalization)")

        // (v) NEGATIVE: GET with If-None-Match: <stale-etag>
        // returns 200 (no match → full response)
        val staleEtag = "W/\"99999-1\""
        val noMatchResp = get(s"$baseUri/index.html", Map("If-None-Match" -> staleEtag))
        assertEquals(noMatchResp.statusCode(), 200,
          clue = s"GET with stale If-None-Match MUST return 200 with full body (no match → full response); got: ${noMatchResp.statusCode()}")
      }
    }
  }

  // Pin the documented Last-Modified HTTP-date FORMAT contract
  // at StaticAssetsHandler.scala lines 70-75 + 99 -- the
  // LAST-MODIFIED-FORMAT pin verifies the documented RFC 7231
  // sec 7.1.1.1 "preferred" HTTP-date format (the RFC 1123 form
  // "Wed, 21 Oct 2015 07:28:00 GMT") emitted via the documented
  // DateTimeFormatter.RFC_1123_DATE_TIME formatter applied to
  // the truncated-to-second mtime in UTC; the documented inline
  // comment at lines 72-73 explains the second-resolution
  // truncation rationale: "HTTP-date is second-resolution.
  // Truncate file mtime so the value we emit can be parsed and
  // compared losslessly by clients on the way back."
  // FORTY-SEVENTH per-emission-site SHAPE pin overall; the
  // Last-Modified format is OPERATIONALLY CRITICAL because:
  // (a) browsers + caching proxies use the Last-Modified value
  // as the If-Modified-Since fallback when ETag is unavailable
  // -- a refactor breaking the format would silently cause
  // revalidation failures, forcing full re-downloads even when
  // the resource hasn't changed, (b) RFC 7231 sec 7.1.1.1
  // mandates the RFC 1123 format as the "preferred" HTTP-date
  // form -- a refactor switching to ISO-8601 or any other
  // format would silently violate the RFC + cause client
  // parsers (browsers, curl --remote-time, generic
  // HttpClient libraries) to reject the value as malformed,
  // (c) the second-resolution truncation is the documented
  // defense for the lossless-round-trip claim -- a refactor
  // dropping the line 73 truncation would emit ms-precision
  // values that clients round to seconds in their
  // If-Modified-Since echo, silently breaking revalidation on
  // every poll (the value the server emitted would never equal
  // the value the client echoes back); per-format regression
  // vectors uniquely caught (NOT caught by 4a49db1's ETag
  // format pin OR 31839af's W/-prefix normalization pin which
  // target the ETag header specifically): (i) refactor
  // switching DateTimeFormatter.RFC_1123_DATE_TIME to any
  // other format (e.g. ISO_INSTANT, ISO_LOCAL_DATE_TIME) would
  // silently violate RFC 7231 sec 7.1.1.1, (ii) refactor
  // switching the zone from ZoneOffset.UTC to a system-local
  // zone would silently emit values with non-GMT zone
  // abbreviations (e.g. "EDT", "PST") that conservative
  // clients reject, (iii) refactor switching to a non-English
  // locale (e.g. via DateTimeFormatter.RFC_1123_DATE_TIME.
  // withLocale(systemLocale)) would silently emit non-English
  // day/month abbreviations (e.g. "Mié, 21 Oct" in Spanish)
  // that ALL HTTP clients reject, (iv) refactor dropping the
  // line 73 second-truncation would silently emit
  // millisecond-precision values that break If-Modified-Since
  // round-trip; test approach: GET /index.html → 200 with
  // Last-Modified header, verify the value (a) matches the
  // RFC 1123 regex pattern with English day/month
  // abbreviations + GMT zone, (b) parses via the documented
  // DateTimeFormatter.RFC_1123_DATE_TIME, (c) the parsed
  // instant is at second-resolution (epoch ms ends in 000),
  // (d) re-fetching is deterministic, (e) the parsed instant
  // equals the file's actual mtime truncated to seconds.
  test("static handler Last-Modified header follows the documented RFC 1123 HTTP-date format with GMT zone + second-resolution truncation per StaticAssetsHandler.scala lines 70-75 + 99's RFC 7231 sec 7.1.1.1 preferred-format contract -- complements the ETag-family pins (4a49db1 format + 31839af weak comparison) by closing the SECOND conditional-request header (the If-Modified-Since fallback when ETag is unavailable)") {
    withStaticSite { staticDir =>
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        val resp = get(s"$baseUri/index.html")
        assertEquals(resp.statusCode(), 200,
          clue = "GET /index.html MUST return 200 so the Last-Modified header is on the response")

        // (i) Last-Modified header is PRESENT on the 200 response
        // per StaticAssetsHandler.scala line 99
        val lastModified = headerValue(resp, "Last-Modified")
          .getOrElse(fail("static handler MUST emit Last-Modified on 200 responses per StaticAssetsHandler.scala line 99"))

        // (ii) Value matches the RFC 1123 HTTP-date pattern with
        // English day-of-week + month abbreviations + GMT zone
        // per RFC 7231 sec 7.1.1.1's "preferred" form (catches
        // refactors that switch format, zone, or locale)
        val rfc1123Pattern = raw"^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \d{1,2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \d{4} \d{2}:\d{2}:\d{2} GMT$$"
        assert(lastModified.matches(rfc1123Pattern),
          clue = s"Last-Modified value MUST match the documented RFC 1123 HTTP-date pattern (English day/month abbreviations + GMT zone) per RFC 7231 sec 7.1.1.1's preferred-format contract; a refactor changing format/zone/locale would silently violate the RFC + break ALL HTTP client parsers; got: $lastModified")

        // (iii) Zone abbreviation is GMT (catches refactor
        // switching from ZoneOffset.UTC to a system-local zone)
        assert(lastModified.endsWith(" GMT"),
          clue = s"Last-Modified value MUST end with ` GMT` per ZoneOffset.UTC + RFC 1123 GMT-zone canonical form; got: $lastModified")

        // (iv) Value PARSES via the documented
        // DateTimeFormatter.RFC_1123_DATE_TIME (catches a
        // structural-pattern-match-but-not-parseable refactor)
        val parsedInstant = scala.util.Try(
          java.time.ZonedDateTime
            .parse(lastModified, java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME)
            .toInstant
        ).getOrElse(fail(s"Last-Modified value MUST parse via DateTimeFormatter.RFC_1123_DATE_TIME (the documented formatter at StaticAssetsHandler.scala line 74); got: $lastModified"))

        // (v) Parsed instant is at second-resolution (epoch ms
        // ends in 000) per the documented line 73 truncation
        // -- catches a refactor dropping the truncation that
        // would silently break If-Modified-Since round-trip
        assertEquals(parsedInstant.toEpochMilli % 1000L, 0L,
          clue = s"parsed Last-Modified instant MUST be at second-resolution (no fractional milliseconds) per StaticAssetsHandler.scala line 73's documented truncation -- a refactor dropping the truncation would silently emit ms-precision values that clients round to seconds in their If-Modified-Since echo, breaking revalidation on every poll; got epochMs: ${parsedInstant.toEpochMilli}")

        // (vi) DETERMINISM: re-fetching the same file produces
        // the identical Last-Modified value (catches a refactor
        // using request-time clock instead of file mtime)
        val resp2 = get(s"$baseUri/index.html")
        assertEquals(headerValue(resp2, "Last-Modified"), Some(lastModified),
          clue = s"Last-Modified value MUST be deterministic across requests for the same unchanged file -- catches a refactor that uses request-time clock instead of file mtime; first=$lastModified, second=${headerValue(resp2, "Last-Modified").getOrElse("<missing>")}")

        // (vii) CROSS-CHECK: the parsed Last-Modified equals
        // the file's actual mtime truncated to seconds per
        // StaticAssetsHandler.scala lines 70-73 (catches a
        // refactor that uses something other than the file's
        // mtime as the source -- e.g. server-start-time,
        // process-create-time, or a hardcoded epoch)
        val actualMtimeMs = java.nio.file.Files.getLastModifiedTime(staticDir.resolve("index.html")).toMillis
        val expectedSecondMs = (actualMtimeMs / 1000L) * 1000L
        assertEquals(parsedInstant.toEpochMilli, expectedSecondMs,
          clue = s"parsed Last-Modified MUST equal the file's actual mtime truncated to seconds per StaticAssetsHandler.scala lines 70-73; a refactor that uses anything other than Files.getLastModifiedTime(target) as the source would silently desync the Last-Modified value from the file's actual modification time, breaking the documented contract; got parsed=${parsedInstant.toEpochMilli}, expectedSecond=$expectedSecondMs (actualMtimeMs=$actualMtimeMs)")
      }
    }
  }

  // Pin the documented If-Modified-Since FALLBACK SEMANTICS
  // contract at StaticAssetsHandler.scala lines 132-141 -- the
  // IMS-FALLBACK pin verifies the documented per-branch behaviors
  // when ifModifiedSince is parsed and compared but If-None-Match
  // is absent (the RFC 7232 sec 3.3 fallback branch). Two
  // specific behaviors are NOT covered by the existing line 10108
  // test (which pins basic same-time -> 304 + past-time -> 200)
  // or the line 10129 test (which pins ETag-takes-priority):
  // (1) MALFORMED dates fall through to 200 via the line 140
  //     `case NonFatal(_) => false` catch -- this is the documented
  //     robustness contract that prevents misbehaving clients
  //     (older browsers, broken proxies sending ISO-8601 or other
  //     non-RFC-1123 formats) from triggering 500 errors and log
  //     amplification on every request, AND
  // (2) FUTURE-DATED clientMs values STILL return 304 because the
  //     line 138 comparison is `lastModifiedSecond <= clientMs`
  //     (not `==`) -- this is the documented defense for CDN-skewed
  //     clocks where a CDN with a clock running slightly fast could
  //     legitimately send If-Modified-Since values in the future
  //     for a file whose mtime is in the past; if the comparison
  //     were `==` (strict equality), such requests would silently
  //     fail revalidation forcing full-body re-fetches on every
  //     poll.
  // FORTY-EIGHTH per-emission-site SHAPE pin overall; the IMS
  // FALLBACK behaviors are OPERATIONALLY CRITICAL because:
  // (a) the parse-error fallback is the documented defense
  //     against log-amplification + client-induced 500 errors --
  //     a refactor swallowing the catch (or re-throwing on
  //     parse failure) would silently amplify per-request log
  //     volume + return 500s for legitimate but old client
  //     date-format submissions, (b) the `<=` semantics handle
  //     the documented CDN-clock-skew scenario where a strict
  //     `==` would silently break revalidation through CDNs that
  //     cache headers with their own clock, (c) the documented
  //     fall-through-to-full-200-on-error path ensures the
  //     server NEVER fails closed on malformed conditional
  //     headers -- it gracefully serves the resource instead;
  // per-format regression vectors uniquely caught (NOT caught
  // by the existing 10108/10129 IMS tests OR the c8cae25
  // Last-Modified format pin which targets EMISSION not
  // PARSING): (i) refactor switching from `NonFatal(_) => false`
  // to `case e => throw e` would silently propagate parse
  // failures up to the outer NonFatal handler at line 193,
  // returning 500 instead of 200, (ii) refactor switching from
  // `NonFatal(_) => false` to `NonFatal(_) => true` would
  // silently grant 304 (don't-send-body) on every parse failure
  // -- effectively allowing clients to skip body downloads by
  // sending garbage IMS values, (iii) refactor switching the
  // line 138 comparison from `<=` to `==` would silently break
  // revalidation for CDN-skewed-forward clocks, (iv) refactor
  // switching `<=` to `>=` (inverse direction) would silently
  // invert the cache semantics -- 304 only when the file IS
  // newer than the client's stored copy, the exact opposite of
  // the documented contract; test approach: GET /index.html ->
  // 200 to capture the file's Last-Modified, then issue 3
  // separate requests covering the 3 uncovered behaviors:
  // (1) If-Modified-Since: "not-a-valid-date" -> 200 (parse
  // error fallback), (2) If-Modified-Since: future-dated RFC
  // 1123 value -> 304 (the `<=` semantics), (3) verify the 304
  // response from the IMS path includes the Last-Modified
  // header per RFC 7232 sec 4.1.
  test("static handler If-Modified-Since FALLBACK SEMANTICS: malformed dates fall through to 200 (NonFatal catch at line 140) and future-dated values still return 304 (the `<=` comparison at line 138) per StaticAssetsHandler.scala lines 132-141's documented parse-error robustness + CDN-clock-skew tolerance contracts -- complements the existing line 10108 test (same-time -> 304, past-time -> 200) + line 10129 test (ETag-takes-priority) by closing the parse-error + future-date dimensions") {
    withStaticSite { staticDir =>
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // Capture the file's documented Last-Modified value
        val initial = get(s"$baseUri/index.html")
        assertEquals(initial.statusCode(), 200,
          clue = "initial GET MUST return 200 to capture the Last-Modified value")
        val emittedLastModified = headerValue(initial, "Last-Modified")
          .getOrElse(fail("server MUST emit Last-Modified on the initial 200 response"))

        // (i) MALFORMED date string -> 200 with full body via
        // the line 140 `case NonFatal(_) => false` catch (parse
        // error treated as "no match" -> not-modified=false ->
        // 200 full response)
        val malformedResp = get(s"$baseUri/index.html",
          Map("If-Modified-Since" -> "not-a-valid-date"))
        assertEquals(malformedResp.statusCode(), 200,
          clue = s"GET with MALFORMED If-Modified-Since MUST return 200 with full body via the line 140 NonFatal catch -- a refactor that re-throws on parse failure would silently return 500 + amplify per-request log volume for legitimate but malformed client dates; got status: ${malformedResp.statusCode()}")
        assert(malformedResp.body().nonEmpty,
          clue = s"200 response from malformed-IMS path MUST include the full body (catches a refactor that returns 200 but with empty body); got body length: ${malformedResp.body().length}")

        // (ii) ISO-8601 format date (which the RFC 1123 parser
        // rejects with DateTimeParseException) -> 200 with full
        // body -- documents that the parser is strictly RFC 1123
        // and does NOT accept ISO-8601 as a fallback (this
        // catches a refactor that broadens the accepted formats
        // and silently weakens the server's strict contract)
        val iso8601Resp = get(s"$baseUri/index.html",
          Map("If-Modified-Since" -> "2026-05-21T14:11:00Z"))
        assertEquals(iso8601Resp.statusCode(), 200,
          clue = s"GET with ISO-8601 If-Modified-Since (which the strict RFC 1123 parser rejects) MUST return 200 with full body via the line 140 NonFatal catch; got status: ${iso8601Resp.statusCode()}")

        // (iii) FUTURE-DATED value -> 304 via the line 138 `<=`
        // semantics: lastModifiedSecond <= clientMs evaluates
        // true when clientMs is in the future, returning
        // not-modified=true -> 304 -- the documented CDN-clock-
        // skew tolerance contract
        val futureDateHttp = java.time.format.DateTimeFormatter.RFC_1123_DATE_TIME
          .format(java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC).plusYears(10))
        val futureResp = get(s"$baseUri/index.html",
          Map("If-Modified-Since" -> futureDateHttp))
        assertEquals(futureResp.statusCode(), 304,
          clue = s"GET with FUTURE-DATED If-Modified-Since MUST return 304 Not Modified per the line 138 `lastModifiedSecond <= clientMs` semantics -- a refactor switching from `<=` to `==` would silently break revalidation through CDNs with skewed-forward clocks (legitimate CDN scenario); got status: ${futureResp.statusCode()}, IMS sent: $futureDateHttp")

        // (iv) 304 response body MUST be empty per RFC 7232 sec 4.1
        assertEquals(futureResp.body(), "",
          clue = s"304 response (from IMS path) MUST be body-less per RFC 7232 sec 4.1 (304 MUST NOT include a message-body); got body length: ${futureResp.body().length}")

        // (v) 304 response from IMS path MUST include the
        // Last-Modified header per RFC 7232 sec 4.1's "SHOULD
        // generate the same headers as a 200 OK would have"
        // contract (and the static handler does so unconditionally
        // since the headers are set BEFORE the 304 branch
        // decision is made at lines 97-99)
        assertEquals(headerValue(futureResp, "Last-Modified"), Some(emittedLastModified),
          clue = s"304 response from IMS path MUST include the Last-Modified header (matching the original 200's value) per RFC 7232 sec 4.1; a refactor that strips Last-Modified on 304 would silently break clients that update their cached Last-Modified to the new value on each successful revalidation; got: ${headerValue(futureResp, "Last-Modified")}, expected: $emittedLastModified")

        // (vi) NEGATIVE: empty If-Modified-Since value -- the
        // ifModifiedSince.exists check at line 132 returns false
        // when the value exists but parsing fails -> 200 with
        // full body (NOT 304). This is a separate edge case
        // from "header absent" (which short-circuits exists()
        // before parsing).
        val emptyImsResp = get(s"$baseUri/index.html",
          Map("If-Modified-Since" -> ""))
        // RFC 7232 sec 3.3 implies a missing IMS header should
        // be ignored, and Java's HttpClient passes through the
        // empty header; the empty-string fails parse -> 200.
        assertEquals(emptyImsResp.statusCode(), 200,
          clue = s"GET with EMPTY If-Modified-Since value MUST return 200 via the line 140 NonFatal catch (empty-string fails RFC 1123 parse); got status: ${emptyImsResp.statusCode()}")
      }
    }
  }

  // Pin the documented Vary: Accept-Encoding CONDITIONAL EMISSION
  // contract at StaticAssetsHandler.scala lines 100-103. The
  // VARY-CONDITIONAL pin verifies the documented closed-set
  // emission policy where Vary: Accept-Encoding is emitted ONLY
  // when the content type is compressible (per WebResponses.scala
  // line 84-89's isCompressibleType -- text/*, application/
  // javascript, application/json, image/svg+xml). Non-compressible
  // content types (image/png, image/jpeg, font/woff2,
  // application/wasm, application/octet-stream, etc.) must NOT
  // emit the Vary header because there is no encoding variation:
  // the server NEVER gzip-compresses these types regardless of
  // the client's Accept-Encoding header, so emitting Vary would
  // mislead caches into partitioning storage by an axis that
  // doesn't actually vary the response. FORTY-NINTH per-emission-
  // site SHAPE pin overall; existing coverage at line 10149-10168
  // verifies the positive case (compressible HTML -> Vary present
  // for both with-Accept-Encoding and without), but the NEGATIVE
  // case (non-compressible content -> Vary ABSENT) is unpinned;
  // the VARY-CONDITIONAL contract is OPERATIONALLY CRITICAL
  // because: (a) caches use Vary to partition stored variants by
  // request header values -- a misleading Vary: Accept-Encoding
  // on a non-compressible response would silently force caches
  // to store separate variants for every distinct Accept-Encoding
  // value (e.g., one for "gzip", another for "gzip, deflate",
  // another for "br, gzip", etc.) even though the actual
  // responses are byte-identical, wasting cache storage + cache
  // hit rate, (b) the documented compressible-type list at
  // WebResponses.scala lines 84-89 is the SOURCE OF TRUTH for
  // the Vary emission policy -- a refactor adding a new
  // compressible type without updating the Vary emission, or
  // dropping the line 102 `if compressible` guard so Vary is
  // emitted unconditionally, would silently desync the variant
  // partitioning from the actual encoding behavior, (c) the
  // unconditional-emission failure mode is especially harmful
  // for high-fanout assets (logos, icons, fonts) where a single
  // mis-emitted Vary multiplies cache pressure across all CDN
  // edge nodes; per-format regression vectors uniquely caught
  // (NOT caught by the existing line 10149-10168 test which
  // covers only compressible content): (i) refactor dropping
  // the line 102 `if compressible` guard would silently emit
  // Vary on non-compressible responses, (ii) refactor changing
  // the Vary value from "Accept-Encoding" to a different token
  // (e.g., adding ", User-Agent" or replacing with "*") would
  // silently break cache partitioning by encoding, (iii) refactor
  // moving the Vary set-call AFTER the 304 sendResponseHeaders
  // call would silently drop Vary from 304 responses (since the
  // HttpExchange container locks headers after sendResponseHeaders),
  // (iv) refactor inverting the conditional (e.g., `if !compressible
  // then set Vary`) would silently invert the contract; test
  // approach: create a static dir with BOTH a compressible file
  // (the default index.html -> text/html) AND a non-compressible
  // file (logo.png -> image/png), then issue 4 GETs covering
  // compressible-with-AE, compressible-without-AE, non-compressible-
  // with-AE, non-compressible-without-AE, plus 2 304 conditional
  // GETs verifying the Vary preserves the conditional emission
  // across the 304 branch.
  test("static handler Vary: Accept-Encoding header is emitted ONLY for compressible content types per StaticAssetsHandler.scala lines 100-103's conditional emission contract + WebResponses.scala lines 84-89's isCompressibleType source-of-truth -- complements the existing line 10149-10168 test (compressible HTML positive case) by closing the NEGATIVE case for non-compressible types (image/png, application/octet-stream, etc.) where Vary must be ABSENT to avoid misleading cache partitioning") {
    withStaticSite { staticDir =>
      // Create a non-compressible asset (PNG -- image/png is
      // not in the WebResponses.scala line 84-89 compressible
      // list). The minimal 8-byte PNG signature suffices since
      // the server classifies by extension at WebResponses.scala
      // line 234, not by content sniffing.
      java.nio.file.Files.write(
        staticDir.resolve("logo.png"),
        Array[Byte](0x89.toByte, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A)
      )

      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // (i) COMPRESSIBLE + Accept-Encoding: gzip
        // -> Vary: Accept-Encoding present (existing coverage,
        // re-asserted for boundary completeness)
        val htmlGz = get(s"$baseUri/index.html",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(htmlGz.statusCode(), 200,
          clue = "compressible HTML with Accept-Encoding: gzip MUST return 200")
        assertEquals(headerValue(htmlGz, "Vary"), Some("Accept-Encoding"),
          clue = s"compressible HTML with Accept-Encoding: gzip MUST emit Vary: Accept-Encoding per StaticAssetsHandler.scala line 103; got: ${headerValue(htmlGz, "Vary")}")

        // (ii) COMPRESSIBLE without Accept-Encoding
        // -> Vary: Accept-Encoding STILL present (the variant
        // declaration semantic -- caches must partition storage
        // even when this particular response is uncompressed)
        val htmlPlain = get(s"$baseUri/index.html")
        assertEquals(htmlPlain.statusCode(), 200,
          clue = "compressible HTML without Accept-Encoding MUST return 200")
        assertEquals(headerValue(htmlPlain, "Vary"), Some("Accept-Encoding"),
          clue = s"compressible HTML without Accept-Encoding MUST STILL emit Vary: Accept-Encoding per StaticAssetsHandler.scala line 103 -- the variant-declaration semantic ensures caches partition storage by encoding regardless of THIS response's encoding; got: ${headerValue(htmlPlain, "Vary")}")

        // (iii) NON-COMPRESSIBLE with Accept-Encoding: gzip
        // -> Vary header MUST BE ABSENT per the line 102
        // `if compressible` guard (the documented closed-set
        // contract -- non-compressible responses NEVER vary by
        // Accept-Encoding because the server NEVER gzips them)
        val pngGz = get(s"$baseUri/logo.png",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(pngGz.statusCode(), 200,
          clue = "non-compressible PNG with Accept-Encoding: gzip MUST return 200")
        assertEquals(headerValue(pngGz, "Vary"), None,
          clue = s"NON-COMPRESSIBLE PNG with Accept-Encoding: gzip MUST NOT emit Vary header per StaticAssetsHandler.scala line 102's `if compressible` guard -- a refactor dropping the guard would silently force caches to partition storage by an axis that doesn't actually vary the response (the server NEVER gzips PNG content); got Vary: ${headerValue(pngGz, "Vary")}")

        // (iv) NON-COMPRESSIBLE Content-Encoding is NOT set
        // (defense-in-depth: confirms the server is actually
        // NOT compressing the non-compressible content, so the
        // Vary-absence contract is semantically correct)
        assertEquals(headerValue(pngGz, "Content-Encoding"), None,
          clue = s"NON-COMPRESSIBLE PNG MUST NOT carry Content-Encoding header (the server never gzips non-compressible types regardless of Accept-Encoding -- this is the semantic basis for the Vary-absence contract); got: ${headerValue(pngGz, "Content-Encoding")}")

        // (v) NON-COMPRESSIBLE without Accept-Encoding
        // -> Vary STILL absent (symmetric with iii)
        val pngPlain = get(s"$baseUri/logo.png")
        assertEquals(pngPlain.statusCode(), 200,
          clue = "non-compressible PNG without Accept-Encoding MUST return 200")
        assertEquals(headerValue(pngPlain, "Vary"), None,
          clue = s"NON-COMPRESSIBLE PNG without Accept-Encoding MUST NOT emit Vary header; got Vary: ${headerValue(pngPlain, "Vary")}")

        // (vi) CONDITIONAL 304 BRANCH PRESERVATION on compressible:
        // when a compressible-type response returns 304, the Vary
        // header MUST still be present (since the line 102-103
        // Vary set-call happens BEFORE the 304 branch decision at
        // line 142 -- catches a refactor that moves the Vary call
        // after sendResponseHeaders, silently dropping it from 304s)
        val htmlEtag = headerValue(htmlPlain, "ETag")
          .getOrElse(fail("server MUST emit ETag on compressible 200 to drive the 304 path"))
        val html304 = get(s"$baseUri/index.html",
          Map("If-None-Match" -> htmlEtag))
        assertEquals(html304.statusCode(), 304,
          clue = s"GET with matching If-None-Match MUST return 304 to drive the 304-preserves-Vary check; got: ${html304.statusCode()}")
        assertEquals(headerValue(html304, "Vary"), Some("Accept-Encoding"),
          clue = s"304 response from compressible type MUST STILL include Vary: Accept-Encoding (the line 102-103 set happens BEFORE the line 142 304 branch); a refactor moving Vary set after sendResponseHeaders would silently drop Vary from 304 responses, breaking cache partitioning for revalidated entries; got: ${headerValue(html304, "Vary")}")

        // (vii) CONDITIONAL 304 BRANCH PRESERVATION on
        // non-compressible: 304 from non-compressible type
        // ALSO has NO Vary (the symmetric absence preserved
        // across the 304 branch)
        val pngEtag = headerValue(pngPlain, "ETag")
          .getOrElse(fail("server MUST emit ETag on non-compressible 200 to drive the 304 path"))
        val png304 = get(s"$baseUri/logo.png",
          Map("If-None-Match" -> pngEtag))
        assertEquals(png304.statusCode(), 304,
          clue = s"GET with matching If-None-Match on PNG MUST return 304 to drive the symmetric-absence check; got: ${png304.statusCode()}")
        assertEquals(headerValue(png304, "Vary"), None,
          clue = s"304 response from NON-compressible type MUST STILL omit Vary (the conditional absence is preserved across the 304 branch -- catches a refactor that adds Vary unconditionally in the 304 path); got: ${headerValue(png304, "Vary")}")

        // (viii) CLOSED-SET assertion: Vary value is EXACTLY
        // "Accept-Encoding" with no extra tokens (catches a
        // refactor that adds additional Vary axes like
        // "Accept-Encoding, User-Agent" or "*" wildcard --
        // both would silently widen the cache partitioning
        // contract beyond the documented Accept-Encoding-only
        // axis)
        val varyValues = Set(htmlGz, htmlPlain, html304)
          .map(r => headerValue(r, "Vary"))
          .flatten
        assertEquals(varyValues, Set("Accept-Encoding"),
          clue = s"the static handler MUST emit EXACTLY one Vary value `Accept-Encoding` across all 3 compressible-response paths (with-AE 200, without-AE 200, 304) -- a refactor adding extra Vary tokens (e.g., User-Agent) or replacing with `*` would silently widen the partitioning axis; got distinct Vary values: $varyValues")
      }
    }
  }

  // Pin the documented 304 RESPONSE SHAPE-INVARIANT contract at
  // StaticAssetsHandler.scala lines 142-143 -- the 304-SHAPE
  // pin verifies the documented closed set of headers that MUST
  // be preserved on a 304 Not Modified response (per RFC 7232
  // sec 4.1's SHOULD-clause) vs the body-specific headers that
  // MUST be DROPPED. Existing 304 tests assert individual
  // dimensions in isolation: body emptiness (31839af + 5ba56c5),
  // ETag presence (31839af), Last-Modified presence (5ba56c5),
  // Vary preservation across 304 (64f3d4f), but the CLOSED-SET
  // SHAPE-INVARIANT assertion -- which simultaneously verifies
  // PRESERVED + ABSENT headers as a single contract -- is
  // unpinned. FIFTIETH per-emission-site SHAPE pin overall
  // (50th milestone); the 304-SHAPE contract is OPERATIONALLY
  // CRITICAL because: (a) RFC 7232 sec 4.1 mandates that a 304
  // response "MUST generate any of the following header fields
  // that would have been sent in a 200 OK response to the same
  // request: Cache-Control, Content-Location, Date, ETag,
  // Expires, and Vary" -- a refactor that strips ANY of these
  // headers from the 304 branch silently violates the RFC and
  // breaks client caches that depend on revalidation header
  // continuity, (b) the static handler's emission order at
  // lines 97-103 (Cache-Control + ETag + Last-Modified + Vary)
  // is BEFORE the line 142 304 branch decision, which means a
  // refactor moving any header set-call AFTER sendResponseHeaders
  // would silently drop it from 304 responses (since
  // HttpExchange locks the response headers map after
  // sendResponseHeaders is called), (c) the body-specific
  // headers Content-Type + Content-Encoding MUST be absent
  // because the 304 response has no body to characterize -- a
  // refactor that pre-emptively sets Content-Type at the top
  // of the handler (e.g., moving the line 145/164/171 set-call
  // before the 304 branch) would silently include Content-Type
  // in 304 responses, potentially confusing aggressive clients
  // that interpret Content-Type on 304 as indicating the body
  // shape; per-format regression vectors uniquely caught (NOT
  // caught by the individual 304 assertions in other pins): (i)
  // refactor stripping any of the 4 cache-revalidation headers
  // (ETag, Last-Modified, Cache-Control, Vary) from the 304
  // path would silently violate RFC 7232 sec 4.1's MUST-clause
  // for these headers (note: RFC says SHOULD for some, MUST for
  // others -- ETag is SHOULD, but our handler unconditionally
  // emits it via the line 98 set-call ordering), (ii) refactor
  // adding Content-Type or Content-Encoding to the 304 branch
  // (or moving them out of the body-emission branches at lines
  // 145/151/164/165/171) would silently include body-specific
  // headers on a body-less response, (iii) refactor that drops
  // any of the 8 security headers from the 304 branch would
  // silently leave revalidated entries unprotected against the
  // documented threats (CSP, X-Frame-Options, CORP, etc.), (iv)
  // refactor that changes the header VALUES between the 200
  // and 304 responses (e.g., emitting different Cache-Control
  // on 304 vs 200, breaking the documented "same headers as
  // 200 OK" contract) would silently desync cache state -- the
  // cross-check assertion below catches this. Test approach:
  // GET with Accept-Encoding: gzip to capture the FULL 200
  // response (compressible variant), then GET with matching
  // If-None-Match + Accept-Encoding: gzip to trigger 304,
  // then cross-check that ALL preserved headers carry IDENTICAL
  // values across the 200 + 304 + verify ABSENT headers + body
  // emptiness.
  test("static handler 304 response SHAPE-INVARIANT: closed set of preserved headers (ETag + Last-Modified + Cache-Control + Vary + 8 security headers) carry IDENTICAL values to the originating 200, while body-specific headers (Content-Type, Content-Encoding) are absent + body is empty per StaticAssetsHandler.scala lines 142-143's documented 304-branch contract + RFC 7232 sec 4.1's SHOULD-clause + applySecurityHeaders inheritance") {
    withStaticSite { staticDir =>
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // (1) Establish the 200 baseline (compressible variant
        // with Accept-Encoding: gzip so the full set including
        // Content-Encoding + Vary is in play)
        val baseline = get(s"$baseUri/index.html",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(baseline.statusCode(), 200,
          clue = "baseline GET MUST return 200 to establish the preserved-header values")

        val baselineEtag = headerValue(baseline, "ETag")
          .getOrElse(fail("baseline 200 MUST emit ETag to drive the If-None-Match revalidation"))
        val baselineLastModified = headerValue(baseline, "Last-Modified")
          .getOrElse(fail("baseline 200 MUST emit Last-Modified"))
        val baselineCacheControl = headerValue(baseline, "Cache-Control")
          .getOrElse(fail("baseline 200 MUST emit Cache-Control"))
        val baselineVary = headerValue(baseline, "Vary")
          .getOrElse(fail("baseline 200 (compressible) MUST emit Vary"))
        val baselineCsp = headerValue(baseline, "Content-Security-Policy")
          .getOrElse(fail("baseline 200 MUST emit Content-Security-Policy"))

        // (2) Trigger 304 via matching If-None-Match
        val revalidated = get(s"$baseUri/index.html",
          Map("If-None-Match" -> baselineEtag, "Accept-Encoding" -> "gzip"))
        assertEquals(revalidated.statusCode(), 304,
          clue = s"GET with matching If-None-Match MUST return 304 to drive the SHAPE-INVARIANT check; got: ${revalidated.statusCode()}")

        // (3) 304 body is empty per RFC 7232 sec 4.1
        assertEquals(revalidated.body(), "",
          clue = s"304 response body MUST be empty per RFC 7232 sec 4.1 (304 MUST NOT include a message-body); got body length: ${revalidated.body().length}")

        // (4) CROSS-CHECK: preserved cache-revalidation headers
        // carry IDENTICAL values to the originating 200 per RFC
        // 7232 sec 4.1's "same headers as 200 OK" contract
        assertEquals(headerValue(revalidated, "ETag"), Some(baselineEtag),
          clue = s"304 ETag MUST equal the 200's ETag per RFC 7232 sec 4.1 (the validator that triggered the 304 is canonical); a refactor changing the ETag emission between 200 and 304 would silently desync client caches; 200=$baselineEtag, 304=${headerValue(revalidated, "ETag")}")
        assertEquals(headerValue(revalidated, "Last-Modified"), Some(baselineLastModified),
          clue = s"304 Last-Modified MUST equal the 200's Last-Modified per RFC 7232 sec 4.1; 200=$baselineLastModified, 304=${headerValue(revalidated, "Last-Modified")}")
        assertEquals(headerValue(revalidated, "Cache-Control"), Some(baselineCacheControl),
          clue = s"304 Cache-Control MUST equal the 200's Cache-Control per RFC 7232 sec 4.1 (Cache-Control is explicitly listed in the SHOULD-clause); 200=$baselineCacheControl, 304=${headerValue(revalidated, "Cache-Control")}")
        assertEquals(headerValue(revalidated, "Vary"), Some(baselineVary),
          clue = s"304 Vary MUST equal the 200's Vary per RFC 7232 sec 4.1 (Vary is explicitly listed in the SHOULD-clause -- without it caches cannot determine whether the 304 applies to the variant they stored); 200=$baselineVary, 304=${headerValue(revalidated, "Vary")}")

        // (5) CROSS-CHECK: 8 security headers preserved across
        // 304 with IDENTICAL values per the applySecurityHeaders
        // inheritance contract (the line 25 call at the top of
        // handle() runs BEFORE the 304 branch decision)
        assertEquals(headerValue(revalidated, "Content-Security-Policy"), Some(baselineCsp),
          clue = s"304 Content-Security-Policy MUST equal the 200's CSP -- security headers MUST be preserved across 304 because revalidated cache entries are served to the user just like the original 200; a refactor that strips CSP from 304 would silently leave revalidated entries unprotected against XSS; 200=$baselineCsp, 304=${headerValue(revalidated, "Content-Security-Policy")}")
        val securityHeaders = Seq(
          "X-Content-Type-Options",
          "X-Frame-Options",
          "Referrer-Policy",
          "Permissions-Policy",
          "Cross-Origin-Opener-Policy",
          "Cross-Origin-Resource-Policy",
          "X-Robots-Tag"
        )
        securityHeaders.foreach { header =>
          assertEquals(headerValue(revalidated, header), headerValue(baseline, header),
            clue = s"304 security header `$header` MUST equal the 200's value (preserved via applySecurityHeaders inheritance through the line 25 set-call ordering BEFORE the line 142 304 branch); a refactor moving applySecurityHeaders after sendResponseHeaders would silently drop ALL security headers from 304 responses, leaving revalidated entries unprotected; 200=${headerValue(baseline, header)}, 304=${headerValue(revalidated, header)}")
        }

        // (6) ABSENCE: body-specific headers MUST NOT be on the
        // 304 response. Content-Type + Content-Encoding are set
        // only in the body-emission branches at lines 145/151/
        // 164/165/171, all of which run AFTER the line 142 304
        // branch decision -- a refactor pre-emptively setting
        // Content-Type at the top of the handler would silently
        // include it on 304 responses (potentially confusing
        // aggressive clients that interpret Content-Type on 304
        // as indicating body shape)
        assertEquals(headerValue(revalidated, "Content-Type"), None,
          clue = s"304 response MUST NOT include Content-Type (no body to characterize) per the static handler's emission ordering at lines 144/164/171 where Content-Type is set only AFTER the 304 branch decision; a refactor that pre-emptively sets Content-Type at the top of the handler would silently include it on 304 responses; got: ${headerValue(revalidated, "Content-Type")}")
        assertEquals(headerValue(revalidated, "Content-Encoding"), None,
          clue = s"304 response MUST NOT include Content-Encoding (no body to encode) per the static handler's emission ordering at lines 151/165 where Content-Encoding is set only in body-emission branches AFTER the 304 branch decision; a refactor that emits Content-Encoding: gzip on 304 (e.g., because the request had Accept-Encoding: gzip) would silently mislead clients into expecting a gzipped body; got: ${headerValue(revalidated, "Content-Encoding")}")

        // (7) CLOSED-SET: the 304 response's server-controlled
        // header set EXACTLY matches the documented preserved
        // header names (excluding Java-HttpServer-added headers
        // like Date + Content-Length that we don't control). The
        // closed-set defense catches a refactor that adds a NEW
        // header to the static handler's emission order without
        // updating the documentation/tests.
        val expectedPreserved = Set(
          "ETag",
          "Last-Modified",
          "Cache-Control",
          "Vary",
          "Content-Security-Policy",
          "Permissions-Policy",
          "Referrer-Policy",
          "X-Content-Type-Options",
          "X-Frame-Options",
          "Cross-Origin-Opener-Policy",
          "Cross-Origin-Resource-Policy",
          "X-Robots-Tag"
        )
        val actualPreserved = expectedPreserved
          .filter(headerValue(revalidated, _).isDefined)
        assertEquals(actualPreserved, expectedPreserved,
          clue = s"304 response MUST include ALL ${expectedPreserved.size} documented preserved headers (4 cache-revalidation + 8 security) -- a refactor dropping any header from the line 97-103 + line 25 applySecurityHeaders set-call sequences would silently weaken the 304 response shape; expected=$expectedPreserved, actual=$actualPreserved, missing=${expectedPreserved -- actualPreserved}")
      }
    }
  }

  // Pin the documented HEAD RESPONSE SHAPE contract at
  // StaticAssetsHandler.scala lines 144-152 -- the HEAD-SHAPE
  // pin verifies the documented "advertise same variant headers
  // as GET" contract per RFC 7231 sec 4.3.2 ("HEAD describes
  // the GET response") + the subtle `wouldCompressIfGet` vs
  // `willCompress` distinction at lines 84-88 where the
  // Content-Encoding emission on HEAD is gated on the documented
  // `wouldCompressIfGet` flag (compressible AND acceptsGzip)
  // NOT the `willCompress` flag (which adds `isGet` to the
  // conjunction and would always be false for HEAD). FIFTY-FIRST
  // per-emission-site SHAPE pin overall; existing coverage at
  // line 9571 verifies HEAD vs GET equality on ETag +
  // Content-Encoding for compressible HTML (gzip + plain
  // variants), but THREE specific dimensions are unpinned:
  // (1) Content-Type IS set on HEAD per line 145 set-call,
  // (2) HEAD on NON-compressible types -- the conditional
  // `wouldCompressIfGet` evaluates false for non-compressible
  // (line 84 isCompressibleType returns false), so HEAD on
  // non-compressible + Accept-Encoding: gzip must NOT emit
  // Content-Encoding (catches a refactor that conditions
  // Content-Encoding on Accept-Encoding alone, ignoring
  // compressibility), (3) the `wouldCompressIfGet` vs
  // `willCompress` distinction -- HEAD on compressible + gzip
  // gets Content-Encoding: gzip even though willCompress is
  // false (because willCompress is gated on isGet at line 88);
  // the HEAD-SHAPE contract is OPERATIONALLY CRITICAL because:
  // (a) RFC 7231 sec 4.3.2 mandates "the server MUST NOT send
  // a message body in the response" but the response MUST
  // include the same "metadata fields" as GET -- a refactor
  // dropping Content-Type from HEAD would silently break HEAD-
  // based cache validation since caches couldn't determine the
  // body shape that GET would return, (b) client caches that
  // VALIDATE via HEAD then FETCH via GET need consistent
  // headers -- if HEAD reports no Content-Encoding but the
  // subsequent GET returns Content-Encoding: gzip, the client
  // cache would invalidate and re-fetch unnecessarily (the
  // documented "advertise same variant headers" contract at
  // the lines 84-88 inline comment + the line 149 inline
  // comment is the explicit defense), (c) the
  // `wouldCompressIfGet` vs `willCompress` distinction is the
  // SUBTLE correctness contract -- a refactor that uses
  // `willCompress` for the HEAD Content-Encoding gate (instead
  // of `wouldCompressIfGet`) would silently emit incorrect
  // headers on HEAD: Content-Encoding would NEVER be set on
  // HEAD because `willCompress` is gated on `isGet` at line 88
  // and `isGet` is false for HEAD; per-format regression vectors
  // uniquely caught (NOT caught by the existing line 9571
  // test): (i) refactor dropping the line 145 Content-Type
  // set-call would silently break HEAD-based cache validation
  // by leaving HEAD responses without the body-shape descriptor,
  // (ii) refactor switching the Content-Encoding gate from
  // `wouldCompressIfGet` to `willCompress` would silently
  // emit incorrect HEAD headers (Content-Encoding always
  // absent on HEAD), (iii) refactor switching from
  // `wouldCompressIfGet` to `acceptsGzip` (dropping the
  // compressibility check) would silently emit Content-Encoding:
  // gzip on HEAD for non-compressible types when Accept-Encoding:
  // gzip is present, (iv) refactor that omits the line 152
  // `sendResponseHeaders(200, -1L)` and instead sends a body
  // (e.g. via writeBytes) would silently violate RFC 7231 sec
  // 4.3.2's no-message-body rule; test approach: create a static
  // dir with BOTH compressible (HTML) AND non-compressible
  // (logo.png) files, then issue 4 HEAD requests covering the
  // 2x2 matrix of (compressible/non-compressible) x (Accept-
  // Encoding: gzip / no-Accept-Encoding), verifying the
  // documented header shapes + body emptiness + status 200 on
  // all variants.
  test("static handler HEAD response SHAPE: Content-Type IS set on HEAD per line 145, Content-Encoding gated on `wouldCompressIfGet` (NOT `willCompress`) per lines 84-88 + 149-151 documented advertising-contract, NON-compressible types never emit Content-Encoding regardless of Accept-Encoding, and body is empty per RFC 7231 sec 4.3.2 -- complements the existing line 9571 HEAD vs GET equality test by closing the Content-Type presence + non-compressible + wouldCompressIfGet-vs-willCompress dimensions") {
    withStaticSite { staticDir =>
      // Create a non-compressible asset (PNG -- image/png is
      // not in the WebResponses.scala line 84-89 compressible
      // list).
      java.nio.file.Files.write(
        staticDir.resolve("logo.png"),
        Array[Byte](0x89.toByte, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A)
      )

      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        def head(path: String, headers: Map[String, String] = Map.empty): HttpResponse[String] =
          val builder = HttpRequest.newBuilder(URI.create(s"$baseUri$path"))
            .method("HEAD", HttpRequest.BodyPublishers.noBody())
          headers.foreach { case (k, v) => builder.header(k, v) }
          httpClient.send(builder.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8))

        // (1) HEAD on COMPRESSIBLE + Accept-Encoding: gzip ->
        // Content-Type set + Content-Encoding: gzip set
        // (wouldCompressIfGet=true via line 84 isCompressible AND
        // line 78 acceptsGzip) + body empty
        val headCompressibleGz = head("/index.html",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(headCompressibleGz.statusCode(), 200,
          clue = "HEAD on compressible + Accept-Encoding: gzip MUST return 200")
        assertEquals(headCompressibleGz.body(), "",
          clue = s"HEAD response body MUST be empty per RFC 7231 sec 4.3.2; got body length: ${headCompressibleGz.body().length}")
        assertEquals(headerValue(headCompressibleGz, "Content-Type"), Some("text/html; charset=utf-8"),
          clue = s"HEAD on compressible MUST emit Content-Type per StaticAssetsHandler.scala line 145 (the body-shape descriptor that caches need to interpret the eventual GET response); got: ${headerValue(headCompressibleGz, "Content-Type")}")
        assertEquals(headerValue(headCompressibleGz, "Content-Encoding"), Some("gzip"),
          clue = s"HEAD on compressible + Accept-Encoding: gzip MUST emit Content-Encoding: gzip per StaticAssetsHandler.scala lines 150-151's `wouldCompressIfGet` gate -- a refactor switching to `willCompress` (which is gated on isGet at line 88) would silently emit NO Content-Encoding on HEAD because isGet is false for HEAD, breaking HEAD-then-GET cache validation; got: ${headerValue(headCompressibleGz, "Content-Encoding")}")

        // (2) HEAD on COMPRESSIBLE without Accept-Encoding ->
        // Content-Type set + Content-Encoding NOT set
        // (wouldCompressIfGet=false because acceptsGzip=false) +
        // body empty
        val headCompressiblePlain = head("/index.html")
        assertEquals(headCompressiblePlain.statusCode(), 200,
          clue = "HEAD on compressible without Accept-Encoding MUST return 200")
        assertEquals(headCompressiblePlain.body(), "",
          clue = s"HEAD body MUST be empty per RFC 7231 sec 4.3.2; got: ${headCompressiblePlain.body().length}")
        assertEquals(headerValue(headCompressiblePlain, "Content-Type"), Some("text/html; charset=utf-8"),
          clue = s"HEAD on compressible (no-gzip path) MUST still emit Content-Type per line 145 -- Content-Type set-call is UNCONDITIONAL on the HEAD branch; got: ${headerValue(headCompressiblePlain, "Content-Type")}")
        assertEquals(headerValue(headCompressiblePlain, "Content-Encoding"), None,
          clue = s"HEAD on compressible without Accept-Encoding MUST NOT emit Content-Encoding per the line 150 `wouldCompressIfGet` gate (acceptsGzip=false -> wouldCompressIfGet=false); got: ${headerValue(headCompressiblePlain, "Content-Encoding")}")

        // (3) HEAD on NON-COMPRESSIBLE + Accept-Encoding: gzip ->
        // Content-Type set + Content-Encoding NOT set despite the
        // gzip-accepting client (wouldCompressIfGet=false because
        // compressible=false at line 84). THIS IS THE UNIQUE
        // SIGNAL OF THIS PIN: a refactor that conditions
        // Content-Encoding on Accept-Encoding alone (ignoring
        // compressibility) would silently emit incorrect headers
        // here.
        val headNonCompressibleGz = head("/logo.png",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(headNonCompressibleGz.statusCode(), 200,
          clue = "HEAD on non-compressible + Accept-Encoding: gzip MUST return 200")
        assertEquals(headNonCompressibleGz.body(), "",
          clue = s"HEAD body MUST be empty per RFC 7231 sec 4.3.2; got: ${headNonCompressibleGz.body().length}")
        assertEquals(headerValue(headNonCompressibleGz, "Content-Type"), Some("image/png"),
          clue = s"HEAD on non-compressible MUST emit Content-Type per line 145 (unconditional on the HEAD branch); got: ${headerValue(headNonCompressibleGz, "Content-Type")}")
        assertEquals(headerValue(headNonCompressibleGz, "Content-Encoding"), None,
          clue = s"HEAD on NON-COMPRESSIBLE + Accept-Encoding: gzip MUST NOT emit Content-Encoding per the line 150 `wouldCompressIfGet` gate (compressible=false at line 84 -> wouldCompressIfGet=false REGARDLESS of acceptsGzip); a refactor that gates Content-Encoding on acceptsGzip alone (dropping the compressibility check) would silently emit Content-Encoding: gzip on HEAD for non-compressible types when client accepts gzip, misleading subsequent GET clients; got: ${headerValue(headNonCompressibleGz, "Content-Encoding")}")

        // (4) HEAD on NON-COMPRESSIBLE without Accept-Encoding ->
        // Content-Type set + Content-Encoding NOT set + body empty
        val headNonCompressiblePlain = head("/logo.png")
        assertEquals(headNonCompressiblePlain.statusCode(), 200,
          clue = "HEAD on non-compressible without Accept-Encoding MUST return 200")
        assertEquals(headNonCompressiblePlain.body(), "",
          clue = s"HEAD body MUST be empty per RFC 7231 sec 4.3.2; got: ${headNonCompressiblePlain.body().length}")
        assertEquals(headerValue(headNonCompressiblePlain, "Content-Type"), Some("image/png"),
          clue = s"HEAD on non-compressible without Accept-Encoding MUST emit Content-Type per line 145; got: ${headerValue(headNonCompressiblePlain, "Content-Type")}")
        assertEquals(headerValue(headNonCompressiblePlain, "Content-Encoding"), None,
          clue = s"HEAD on non-compressible without Accept-Encoding MUST NOT emit Content-Encoding; got: ${headerValue(headNonCompressiblePlain, "Content-Encoding")}")

        // (5) CROSS-CHECK with GET: HEAD variant headers
        // (Content-Type, Content-Encoding) MATCH the GET variant
        // headers exactly for the same request shape -- the
        // documented "HEAD describes GET" contract per RFC 7231
        // sec 4.3.2
        val getCompressibleGz = get(s"$baseUri/index.html",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(headerValue(headCompressibleGz, "Content-Type"),
                     headerValue(getCompressibleGz, "Content-Type"),
          clue = s"HEAD Content-Type MUST equal GET Content-Type for the same request shape (compressible + gzip) per RFC 7231 sec 4.3.2 -- catches a refactor that diverges the Content-Type emission between HEAD and GET branches; HEAD=${headerValue(headCompressibleGz, "Content-Type")}, GET=${headerValue(getCompressibleGz, "Content-Type")}")
        assertEquals(headerValue(headCompressibleGz, "Content-Encoding"),
                     headerValue(getCompressibleGz, "Content-Encoding"),
          clue = s"HEAD Content-Encoding MUST equal GET Content-Encoding for the same request shape (compressible + gzip) per RFC 7231 sec 4.3.2 -- catches a refactor that uses `willCompress` for HEAD instead of `wouldCompressIfGet`, which would silently produce Content-Encoding: gzip on GET but None on HEAD, invalidating client cache entries on HEAD-then-GET workflows; HEAD=${headerValue(headCompressibleGz, "Content-Encoding")}, GET=${headerValue(getCompressibleGz, "Content-Encoding")}")

        // (6) wouldCompressIfGet vs willCompress DOCUMENTED
        // DISTINCTION: the test in (1) + (5) PROVES that HEAD
        // emits Content-Encoding: gzip even though `willCompress`
        // would be false for HEAD (willCompress is gated on
        // isGet at line 88). A refactor switching the HEAD gate
        // from `wouldCompressIfGet` to `willCompress` would
        // BREAK (1) above. This 6th tier is the EXPLICIT
        // DOCUMENTATION of the contract semantics via the
        // distinct test cases above -- captured here for
        // discoverability.
        assertEquals(headerValue(headCompressibleGz, "Content-Encoding"), Some("gzip"),
          clue = "DOCUMENTATION SENTINEL: this assertion is the wouldCompressIfGet-vs-willCompress correctness gate -- if it fails, the HEAD path is using `willCompress` (gated on isGet=false for HEAD) instead of `wouldCompressIfGet`, silently emitting NO Content-Encoding on HEAD for the compressible+gzip variant")

        // (7) HEAD variant ETag carries the -gz suffix when
        // wouldCompressIfGet=true (preserved from the GET path's
        // line 93 etag template) -- catches a refactor that
        // diverges the ETag generation between HEAD and GET
        // branches (the ETag is set at line 98 BEFORE the HEAD
        // branch decision, so it carries the wouldCompressIfGet
        // suffix correctly)
        val headEtag = headerValue(headCompressibleGz, "ETag")
          .getOrElse(fail("HEAD on compressible+gzip MUST emit ETag per the line 98 set-call before the HEAD branch"))
        assert(headEtag.endsWith("-gz\""),
          clue = s"HEAD ETag MUST carry the -gz suffix when wouldCompressIfGet=true per the documented gzip-variant disambiguation at StaticAssetsHandler.scala line 93; a refactor that drops the suffix on HEAD ETags would silently break the variant-disambiguation contract; got: $headEtag")
      }
    }
  }

  // Pin the documented JSON-HANDLER HEAD RESPONSE SHAPE contract
  // at WebResponses.scala writeBytes lines 165-207 -- the
  // JSON-HEAD-SHAPE pin verifies the documented HEAD-branch
  // headers on the JSON-API endpoints that flow through
  // writeBytes (which is the unified code path used by both
  // writeJson and writePlain). FIFTY-SECOND per-emission-site
  // SHAPE pin overall; existing coverage at line 9617 verifies
  // HEAD vs GET Content-Encoding equality + Vary presence on
  // /api/health, but THREE specific dimensions are unpinned:
  // (1) Content-Type IS set on HEAD per line 172 (the
  // UNCONDITIONAL set-call BEFORE the HEAD branch decision),
  // (2) Cache-Control: no-store IS set on HEAD per line 173
  // (UNCONDITIONAL set-call before the HEAD branch -- a refactor
  // that moves applySecurityHeaders/writeBytes set-calls after
  // sendResponseHeaders would silently drop Cache-Control from
  // HEAD responses), (3) CLOSED-SET assertion verifying the
  // complete documented set of headers on the JSON-HEAD response,
  // which catches a refactor that adds NEW headers to writeBytes
  // without updating the documentation/tests; the JSON-HEAD-SHAPE
  // contract is OPERATIONALLY CRITICAL because: (a) RFC 7231 sec
  // 4.3.2 mandates the HEAD response "MUST include the same
  // metadata fields as GET" -- a refactor dropping Content-Type
  // from JSON HEAD would silently leave caches without the
  // body-shape descriptor needed to interpret the eventual GET,
  // (b) Cache-Control: no-store is the documented "JSON
  // responses are never cached" contract -- the JSON-API surface
  // returns user-specific or time-sensitive data (rate-limit
  // state, queue depth, draining flag, hero data) where caching
  // would silently leak stale state across users or across time,
  // (c) the parallel-handler-types contract is the documented
  // invariant: BOTH StaticAssetsHandler.scala line 144-152 AND
  // WebResponses.scala writeBytes line 189-207 emit the SAME
  // HEAD-response shape (the lines 177-187 inline comment in
  // WebResponses.scala explicitly says "this mirrors it for JSON
  // responses... so every HEAD response across the server
  // advertises Content-Encoding: gzip when the equivalent GET
  // would compress") -- a refactor diverging the two handler
  // types' HEAD-response shapes would silently break the
  // documented unified contract that operator monitoring depends
  // on; per-format regression vectors uniquely caught (NOT
  // caught by the existing line 9617 test which only verifies
  // Content-Encoding equality + Vary presence + body empty):
  // (i) refactor dropping the line 172 Content-Type set-call
  // would silently break JSON-HEAD-based cache validation,
  // (ii) refactor moving the line 173 Cache-Control set-call
  // after sendResponseHeaders would silently drop Cache-Control
  // from HEAD responses, allowing caches to STORE the empty
  // HEAD response indefinitely + then serve it to subsequent
  // GET requests, (iii) refactor diverging the JsonHandler HEAD
  // shape from the StaticAssetsHandler HEAD shape would silently
  // break the documented unified contract -- the parallel
  // pin pair (THIS commit + 41ff9b4) ensures BOTH handler types
  // are explicitly verified; test approach: HEAD on /api/health
  // (the canonical large-JSON endpoint that's well over
  // MinGzipSize per the existing test's documented analysis) with
  // and without Accept-Encoding: gzip, verify the documented
  // header shape + body emptiness + CROSS-CHECK with GET on the
  // same endpoint + CROSS-CHECK Content-Type with the static-
  // handler HEAD pin for the parallel-handler-types contract.
  test("JSON-handler HEAD response SHAPE: Content-Type IS set on HEAD per WebResponses.scala writeBytes line 172, Cache-Control: no-store IS set per line 173, Vary: Accept-Encoding set per line 175 (when compressible), Content-Encoding gated on wouldCompressIfGet at lines 188+205, body empty per RFC 7231 sec 4.3.2 -- complements the existing line 9617 test (Content-Encoding equality + Vary) by closing the Content-Type + Cache-Control + closed-set dimensions on the JSON-API HEAD path") {
    withStaticSite { staticDir =>
      withServer(staticDir) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        def head(acceptEncoding: Option[String]): HttpResponse[String] =
          val builder = HttpRequest.newBuilder(URI.create(s"$baseUri/api/health"))
            .method("HEAD", HttpRequest.BodyPublishers.noBody())
          acceptEncoding.foreach(builder.header("Accept-Encoding", _))
          httpClient.send(builder.build(), HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8))

        // (1) HEAD on /api/health + Accept-Encoding: gzip
        // -> Content-Type set + Cache-Control: no-store set +
        // Vary set + Content-Encoding: gzip set + body empty +
        // status 200
        val headGz = head(Some("gzip"))
        assertEquals(headGz.statusCode(), 200,
          clue = "HEAD on /api/health + gzip MUST return 200")
        assertEquals(headGz.body(), "",
          clue = s"JSON-handler HEAD response body MUST be empty per RFC 7231 sec 4.3.2 + WebResponses.scala line 207's sendResponseHeaders(status, -1L); got body length: ${headGz.body().length}")
        assertEquals(headerValue(headGz, "Content-Type"), Some("application/json; charset=utf-8"),
          clue = s"JSON-handler HEAD MUST emit Content-Type per WebResponses.scala line 172's UNCONDITIONAL set-call (before the HEAD branch decision at line 189) -- the body-shape descriptor that caches need to interpret the eventual GET response; a refactor that moves Content-Type set-call inside an `if !isHead` branch would silently break HEAD-based cache validation; got: ${headerValue(headGz, "Content-Type")}")
        assertEquals(headerValue(headGz, "Cache-Control"), Some("no-store"),
          clue = s"JSON-handler HEAD MUST emit Cache-Control: no-store per WebResponses.scala line 173's UNCONDITIONAL set-call -- the documented `JSON responses never cached` contract that prevents stale state across users; a refactor that moves Cache-Control set-call inside an `if !isHead` branch would silently allow caches to STORE the empty HEAD response indefinitely + serve it to subsequent GETs (silently caching the user-specific data); got: ${headerValue(headGz, "Cache-Control")}")
        assertEquals(headerValue(headGz, "Vary"), Some("Accept-Encoding"),
          clue = s"JSON-handler HEAD MUST emit Vary: Accept-Encoding for compressible responses per WebResponses.scala line 175's conditional set-call; got: ${headerValue(headGz, "Vary")}")
        assertEquals(headerValue(headGz, "Content-Encoding"), Some("gzip"),
          clue = s"JSON-handler HEAD on compressible + gzip MUST emit Content-Encoding: gzip per WebResponses.scala lines 188+205 wouldCompressIfGet gate -- the documented `HEAD describes GET` contract; got: ${headerValue(headGz, "Content-Encoding")}")

        // (2) HEAD on /api/health without Accept-Encoding ->
        // Content-Type set + Cache-Control set + Vary set
        // (compressible regardless of Accept-Encoding) +
        // Content-Encoding NOT set + body empty + status 200
        val headPlain = head(None)
        assertEquals(headPlain.statusCode(), 200,
          clue = "HEAD on /api/health no-gzip MUST return 200")
        assertEquals(headPlain.body(), "",
          clue = s"HEAD body MUST be empty per RFC 7231 sec 4.3.2; got: ${headPlain.body().length}")
        assertEquals(headerValue(headPlain, "Content-Type"), Some("application/json; charset=utf-8"),
          clue = s"JSON-handler HEAD (no-gzip path) MUST still emit Content-Type per WebResponses.scala line 172 (UNCONDITIONAL); got: ${headerValue(headPlain, "Content-Type")}")
        assertEquals(headerValue(headPlain, "Cache-Control"), Some("no-store"),
          clue = s"JSON-handler HEAD (no-gzip path) MUST still emit Cache-Control: no-store per line 173 (UNCONDITIONAL); got: ${headerValue(headPlain, "Cache-Control")}")
        assertEquals(headerValue(headPlain, "Vary"), Some("Accept-Encoding"),
          clue = s"JSON-handler HEAD (no-gzip path) MUST still emit Vary: Accept-Encoding per line 175 (compressible content type triggers Vary regardless of Accept-Encoding header -- the variant-declaration semantic); got: ${headerValue(headPlain, "Vary")}")
        assertEquals(headerValue(headPlain, "Content-Encoding"), None,
          clue = s"JSON-handler HEAD (no-gzip path) MUST NOT emit Content-Encoding per the line 188 wouldCompressIfGet gate (acceptsGzip=false); got: ${headerValue(headPlain, "Content-Encoding")}")

        // (3) CROSS-CHECK with GET on /api/health: HEAD variant
        // headers (Content-Type, Cache-Control, Vary,
        // Content-Encoding) MATCH the GET variant headers
        // exactly for the same request shape per RFC 7231 sec
        // 4.3.2 ("HEAD describes GET")
        val getGz = get(s"$baseUri/api/health",
          Map("Accept-Encoding" -> "gzip"))
        assertEquals(headerValue(headGz, "Content-Type"),
                     headerValue(getGz, "Content-Type"),
          clue = s"JSON-handler HEAD Content-Type MUST equal GET Content-Type for /api/health per RFC 7231 sec 4.3.2; HEAD=${headerValue(headGz, "Content-Type")}, GET=${headerValue(getGz, "Content-Type")}")
        assertEquals(headerValue(headGz, "Cache-Control"),
                     headerValue(getGz, "Cache-Control"),
          clue = s"JSON-handler HEAD Cache-Control MUST equal GET Cache-Control for /api/health per RFC 7231 sec 4.3.2 -- both MUST be no-store (the JSON API contract); HEAD=${headerValue(headGz, "Cache-Control")}, GET=${headerValue(getGz, "Cache-Control")}")
        assertEquals(headerValue(headGz, "Vary"),
                     headerValue(getGz, "Vary"),
          clue = s"JSON-handler HEAD Vary MUST equal GET Vary per RFC 7231 sec 4.3.2; HEAD=${headerValue(headGz, "Vary")}, GET=${headerValue(getGz, "Vary")}")
        assertEquals(headerValue(headGz, "Content-Encoding"),
                     headerValue(getGz, "Content-Encoding"),
          clue = s"JSON-handler HEAD Content-Encoding MUST equal GET Content-Encoding for the same request shape per RFC 7231 sec 4.3.2 + WebResponses.scala lines 177-187's `mirrors the static handler for JSON responses` documented contract; HEAD=${headerValue(headGz, "Content-Encoding")}, GET=${headerValue(getGz, "Content-Encoding")}")

        // (4) PARALLEL-HANDLER-TYPES CROSS-CHECK: the JSON-HEAD
        // response Content-Type contract is the SAME shape as
        // the static-handler HEAD (41ff9b4 pin) -- both MUST
        // emit Content-Type per their respective documented
        // set-call sites BEFORE their HEAD branch decisions.
        // The static handler emits Content-Type at line 145
        // INSIDE the HEAD branch; the JSON handler emits it at
        // line 172 BEFORE the HEAD branch. Both produce
        // Content-Type on HEAD, but the structural difference
        // means a refactor relocating either set-call could
        // silently break one handler type while leaving the
        // other working. THIS assertion is the explicit
        // documentation of the unified parallel-contract:
        val staticHead = HttpRequest.newBuilder(URI.create(s"$baseUri/index.html"))
          .method("HEAD", HttpRequest.BodyPublishers.noBody())
          .build()
        val staticHeadResp = httpClient.send(staticHead, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8))
        assert(headerValue(staticHeadResp, "Content-Type").isDefined,
          clue = s"STATIC-handler HEAD MUST emit Content-Type (parallel-handler-types contract with JSON HEAD); got: ${headerValue(staticHeadResp, "Content-Type")}")
        assert(headerValue(headGz, "Content-Type").isDefined,
          clue = s"JSON-handler HEAD MUST emit Content-Type (parallel-handler-types contract with STATIC HEAD); got: ${headerValue(headGz, "Content-Type")}")

        // (5) CLOSED-SET assertion: the JSON-HEAD response
        // server-controlled header set EXACTLY includes the
        // documented preserved header names. Catches a refactor
        // that adds NEW headers to writeBytes without updating
        // the documentation/tests.
        val expectedHeadHeaders = Set(
          "Content-Type",
          "Cache-Control",
          "Vary",
          "Content-Encoding",
          // Security headers from applySecurityHeaders
          "Content-Security-Policy",
          "Permissions-Policy",
          "Referrer-Policy",
          "X-Content-Type-Options",
          "X-Frame-Options",
          "Cross-Origin-Opener-Policy",
          "Cross-Origin-Resource-Policy",
          "X-Robots-Tag"
        )
        val actualHeadHeaders = expectedHeadHeaders
          .filter(headerValue(headGz, _).isDefined)
        assertEquals(actualHeadHeaders, expectedHeadHeaders,
          clue = s"JSON-handler HEAD response MUST include ALL ${expectedHeadHeaders.size} documented headers (4 content + 8 security) on the compressible+gzip path; a refactor dropping any header from the writeBytes lines 172-175 + applySecurityHeaders set-call sequences would silently weaken the JSON-HEAD response shape; expected=$expectedHeadHeaders, actual=$actualHeadHeaders, missing=${expectedHeadHeaders -- actualHeadHeaders}")
      }
    }
  }

  // Pin the documented status-poll MESSAGE-TEXT VALUES SET
  // contract at JobQueue.scala lines 395 + 403 + 701 + 709 --
  // the MESSAGE-VALUES-SET pin consolidates the 4 documented
  // non-terminal-state message texts emitted across BOTH
  // submission endpoints (analyze + hall) x BOTH non-terminal
  // states (Queued + Running) into a single CLOSED-SET
  // assertion. FIFTY-THIRD per-emission-site SHAPE pin overall;
  // existing per-state per-endpoint pins (016d138 analyze
  // Queued + 65b46f6 analyze Running + 92e3ea2 hall Running +
  // c0dffd5 hall Queued) verify the individual message strings
  // in isolation, but the CONSOLIDATED VALUES SET shape --
  // which verifies CARDINALITY + DISAMBIGUATION + CROSS-STATE
  // + CROSS-ENDPOINT invariants in a single test -- is unpinned;
  // the MESSAGE-VALUES-SET contract is OPERATIONALLY CRITICAL
  // because: (a) operator dashboards + user-facing UI render
  // distinct visual states based on these 4 message strings --
  // a refactor that COLLAPSES two messages (e.g., uses "Queued"
  // for both analyze and hall) would silently break the
  // endpoint-disambiguation contract that lets dashboards
  // partition the queue-wait metric by job type, (b) the
  // documented design intentionally uses DISTINCT messages on
  // analyze vs hall (4 distinct strings, not 2 shared) to
  // support per-endpoint operator analytics -- a refactor that
  // SWAPS analyze and hall messages would silently flip the
  // dashboard partitioning, (c) the 4 message strings are the
  // SOURCE OF TRUTH for the user-visible queue+running phase
  // labels -- a refactor that adds a 5th message variant (e.g.,
  // splitting Running into "Analyzing flop" vs "Analyzing
  // turn") without updating documentation would silently widen
  // the contract; per-format regression vectors uniquely
  // caught (NOT caught by the individual per-state per-endpoint
  // pins): (i) refactor that uses the SAME message text on
  // analyze + hall (e.g., both Queued states emit "Queued")
  // would silently violate the documented endpoint-
  // disambiguation invariant -- the individual pins would PASS
  // independently (each asserting its expected text) but the
  // SET cardinality would silently drop from 4 to 2 or 3,
  // (ii) refactor that COLLAPSES Queued + Running into a single
  // message (e.g., "Processing") would silently violate the
  // state-disambiguation contract -- the individual pins would
  // PASS but the SET cardinality would drop, (iii) refactor
  // that adds a 5th message variant would NOT be caught by
  // individual pins (which only assert ==) but WOULD be caught
  // by the CLOSED-SET assertion, (iv) refactor that
  // accidentally swaps the analyze + hall Queued messages
  // (e.g., analyze emits "Queued for playing hall" + hall
  // emits "Queued for analysis") -- the individual pins
  // WOULD catch the per-endpoint-specific assertion BUT the
  // CROSS-STATE DISAMBIGUATION CLOSED-SET catches the SAME
  // failure with a different diagnostic angle, providing
  // defense-in-depth via the SET-cardinality signal; test
  // approach: spin up a single server with BlockingBackend
  // (analyze) + BlockingPlayingHallBackend (hall) at
  // maxConcurrentJobs=1, submit 4 jobs (analyze1 + analyze2
  // + hall1 + hall2) such that analyze1+hall1 reach Running
  // state and analyze2+hall2 stay Queued, poll all 4 to capture
  // the message texts, then assert the SET cardinality +
  // VALUES + CROSS-STATE + CROSS-ENDPOINT disambiguations.
  test("status-poll non-terminal-state message-text CLOSED SET contract: the 4 documented message strings emitted across (Queued + Running) x (analyze + hall) MUST form a SET of EXACTLY 4 distinct values {`Queued for analysis`, `Analysis in progress`, `Queued for playing hall`, `Playing hall run in progress`} per JobQueue.scala lines 395 + 403 + 701 + 709 -- the CONSOLIDATED VALUES SET pin closes the gap left by the per-state per-endpoint pins which verify INDIVIDUAL strings but not the SET cardinality / disambiguation invariants") {
    withStaticSite { staticDir =>
      val analyzeBackend = new BlockingBackend(Right(sampleAnalysisResult))
      val hallBackend = new BlockingPlayingHallBackend(Right(samplePlayingHallResult))
      // maxConcurrentJobs=2 because analyze + hall share the
      // SAME analysisExecutor thread pool (per
      // HandHistoryReviewServerRuntime.scala lines 52 + 58
      // both passing the same executor reference) -- 2 slots
      // lets analyze1 + hall1 both reach Running while
      // analyze2 + hall2 stay Queued
      withServer(staticDir, backend = analyzeBackend, playingHallBackend = hallBackend,
                 maxConcurrentJobs = 2) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        try
          // (1) Submit analyze1 -> Running (BlockingBackend
          // blocks it indefinitely until released)
          val analyze1 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
          assertEquals(analyze1.statusCode(), 202,
            clue = "analyze1 submission MUST return 202 to enter the Running state")
          assert(analyzeBackend.started.await(3, TimeUnit.SECONDS),
            "analyze BlockingBackend never started -- the analyze1 job MUST enter the analyze call to saturate the worker pool BEFORE submitting analyze2")
          val analyze1StatusUri = s"$baseUri${jsonBody(analyze1)("statusUrl").str}"

          // (2) Submit hall1 -> Running (BlockingPlayingHallBackend
          // blocks it indefinitely until released)
          val hall1 = postJson(s"$baseUri/api/playing-hall", validUploadPayload)
          assertEquals(hall1.statusCode(), 202,
            clue = "hall1 submission MUST return 202 to enter the Running state")
          assert(hallBackend.started.await(3, TimeUnit.SECONDS),
            "hall BlockingPlayingHallBackend never started -- the hall1 job MUST enter the playing-hall call to saturate the worker pool BEFORE submitting hall2")
          val hall1StatusUri = s"$baseUri${jsonBody(hall1)("statusUrl").str}"

          // (3) Submit analyze2 -> Queued (analyze worker pool
          // saturated by analyze1)
          val analyze2 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
          assertEquals(analyze2.statusCode(), 202,
            clue = "analyze2 submission MUST return 202 -- gets Queued because analyze1 saturates the analyze worker pool at maxConcurrentJobs=1")
          val analyze2StatusUri = s"$baseUri${jsonBody(analyze2)("statusUrl").str}"

          // (4) Submit hall2 -> Queued (hall worker pool
          // saturated by hall1)
          val hall2 = postJson(s"$baseUri/api/playing-hall", validUploadPayload)
          assertEquals(hall2.statusCode(), 202,
            clue = "hall2 submission MUST return 202 -- gets Queued because hall1 saturates the hall worker pool at maxConcurrentJobs=1")
          val hall2StatusUri = s"$baseUri${jsonBody(hall2)("statusUrl").str}"

          // (5) Poll all 4 jobs to capture message texts
          val analyze1Body = getJson(analyze1StatusUri)
          val hall1Body = getJson(hall1StatusUri)
          val analyze2Body = getJson(analyze2StatusUri)
          val hall2Body = getJson(hall2StatusUri)

          // Sanity-check the state phases first to confirm
          // the test setup is correct
          assertEquals(analyze1Body("status").str, "running",
            clue = "analyze1 MUST be in Running state to capture the Running message text")
          assertEquals(hall1Body("status").str, "running",
            clue = "hall1 MUST be in Running state to capture the hall Running message text")
          assertEquals(analyze2Body("status").str, "queued",
            clue = "analyze2 MUST be in Queued state to capture the Queued message text")
          assertEquals(hall2Body("status").str, "queued",
            clue = "hall2 MUST be in Queued state to capture the hall Queued message text")

          // (6) CAPTURE message texts
          val analyzeQueuedMsg = analyze2Body("message").str
          val analyzeRunningMsg = analyze1Body("message").str
          val hallQueuedMsg = hall2Body("message").str
          val hallRunningMsg = hall1Body("message").str

          // (7) VALUES SET assertion: SET cardinality MUST be 4
          // (no duplicates -- catches a refactor that uses the
          // SAME message text on multiple states/endpoints)
          val messageSet = Set(analyzeQueuedMsg, analyzeRunningMsg, hallQueuedMsg, hallRunningMsg)
          assertEquals(messageSet.size, 4,
            clue = s"the 4 message texts emitted across (Queued + Running) x (analyze + hall) MUST form a SET of EXACTLY 4 distinct values per JobQueue.scala lines 395 + 403 + 701 + 709 -- a refactor that COLLAPSES any two messages into the same text would silently violate the documented disambiguation contract that operator dashboards depend on; got SET cardinality: ${messageSet.size}, values: $messageSet")

          // (8) SET EQUALITY: the 4 message strings MUST match
          // the documented closed-set exactly (catches a
          // refactor that REPHRASES any of the 4 strings while
          // preserving cardinality)
          val expectedSet = Set(
            "Queued for analysis",
            "Analysis in progress",
            "Queued for playing hall",
            "Playing hall run in progress"
          )
          assertEquals(messageSet, expectedSet,
            clue = s"the 4 status-poll message texts MUST be EXACTLY the documented closed-set per JobQueue.scala lines 395 + 403 + 701 + 709 -- a refactor rephrasing any message (e.g. to 'Awaiting analysis' or 'Processing in the hall') would silently change user-visible text without UI review + break operator dashboards that grep for the documented strings; got=$messageSet, expected=$expectedSet, missing=${expectedSet -- messageSet}, extra=${messageSet -- expectedSet}")

          // (9) CROSS-STATE DISAMBIGUATION: Queued vs Running
          // messages MUST differ on each endpoint (catches a
          // refactor that uses the same text for both states)
          assertNotEquals(analyzeQueuedMsg, analyzeRunningMsg,
            clue = s"analyze Queued message MUST differ from analyze Running message per the documented state-disambiguation contract -- a refactor using the same text for both states would silently break the frontend's spinner-vs-queue-position rendering distinction; Queued=$analyzeQueuedMsg, Running=$analyzeRunningMsg")
          assertNotEquals(hallQueuedMsg, hallRunningMsg,
            clue = s"hall Queued message MUST differ from hall Running message per the documented state-disambiguation contract; Queued=$hallQueuedMsg, Running=$hallRunningMsg")

          // (10) CROSS-ENDPOINT DISAMBIGUATION: analyze vs hall
          // messages MUST differ on each state (catches a
          // refactor that uses the same text across endpoints)
          assertNotEquals(analyzeQueuedMsg, hallQueuedMsg,
            clue = s"analyze Queued message MUST differ from hall Queued message per the documented endpoint-disambiguation contract -- a refactor using the same text across endpoints would silently break dashboards partitioning the queue-wait metric by job type; analyze=$analyzeQueuedMsg, hall=$hallQueuedMsg")
          assertNotEquals(analyzeRunningMsg, hallRunningMsg,
            clue = s"analyze Running message MUST differ from hall Running message per the documented endpoint-disambiguation contract; analyze=$analyzeRunningMsg, hall=$hallRunningMsg")

          // (11) STRUCTURAL SHAPE: analyze messages contain the
          // word "analysis" (case-insensitive) and hall messages
          // contain the word "hall" (catches a confusion swap
          // where the analyze message gets the hall token + vice
          // versa)
          assert(analyzeQueuedMsg.toLowerCase.contains("analysis"),
            clue = s"analyze Queued message MUST contain the word `analysis` per the documented endpoint-discriminator token -- a refactor that swaps analyze + hall message tokens would silently flip the dashboard partitioning; got: $analyzeQueuedMsg")
          assert(analyzeRunningMsg.toLowerCase.contains("analysis"),
            clue = s"analyze Running message MUST contain the word `analysis`; got: $analyzeRunningMsg")
          assert(hallQueuedMsg.toLowerCase.contains("hall"),
            clue = s"hall Queued message MUST contain the word `hall` per the documented endpoint-discriminator token; got: $hallQueuedMsg")
          assert(hallRunningMsg.toLowerCase.contains("hall"),
            clue = s"hall Running message MUST contain the word `hall`; got: $hallRunningMsg")

          // (12) STATE-DISCRIMINATOR TOKENS: Queued messages
          // start with "Queued" (catches state-token drift);
          // Running messages contain a progress-indicator token
          // ("progress" or "Analysis" without "Queued for"
          // prefix) per the documented running-state semantics
          assert(analyzeQueuedMsg.startsWith("Queued"),
            clue = s"analyze Queued message MUST start with `Queued` per the documented state-discriminator token; got: $analyzeQueuedMsg")
          assert(hallQueuedMsg.startsWith("Queued"),
            clue = s"hall Queued message MUST start with `Queued`; got: $hallQueuedMsg")
          assert(!analyzeRunningMsg.startsWith("Queued"),
            clue = s"analyze Running message MUST NOT start with `Queued` (state-token drift catch); got: $analyzeRunningMsg")
          assert(!hallRunningMsg.startsWith("Queued"),
            clue = s"hall Running message MUST NOT start with `Queued` (state-token drift catch); got: $hallRunningMsg")
        finally
          // Release both blocking backends so the server can
          // shut down cleanly (otherwise withServer's shutdown
          // grace would wait for the blocking workers to finish)
          analyzeBackend.release.countDown()
          hallBackend.release.countDown()
      }
    }
  }

  // Pin the documented profile-update PARTIAL-UPDATE
  // ASYMMETRY contract at PlatformUserAuth.scala lines
  // 669-672 -- the PARTIAL-UPDATE-ASYMMETRY pin verifies the
  // documented inconsistency where:
  //   (a) displayName -- if the request omits / nulls /
  //       empties the field, the EXISTING value is PRESERVED
  //       (line 669: `sanitizeDisplayName(displayName)
  //       .getOrElse(current.profile.displayName)`),
  //   (b) heroName, preferredSite, timeZone -- if the request
  //       omits / nulls / empties the field, the EXISTING
  //       value is CLEARED to None (lines 670-672:
  //       `sanitizeOptionalField(...)` returns None for
  //       missing input WITHOUT any getOrElse fallback to
  //       current value).
  // FIFTY-FOURTH per-emission-site SHAPE pin overall; the
  // existing line 16981 test pins the 7-field auth-state
  // SHAPE-INVARIANCE on the profile-update response, but the
  // documented per-field PARTIAL-UPDATE asymmetry semantic is
  // unpinned; the ASYMMETRY contract is OPERATIONALLY
  // CRITICAL because: (a) the documented design intentionally
  // makes displayName "sticky" -- the frontend UI never has
  // to re-send displayName when updating other fields,
  // simplifying the form-submit logic and preventing
  // accidental displayName clearing when the user updates
  // their preferred-site dropdown without touching the
  // display-name input, (b) the documented design
  // intentionally makes heroName / preferredSite / timeZone
  // "ephemeral" -- a user clears these fields by submitting
  // a form with empty/null values, which the frontend can do
  // implicitly without a dedicated "clear" button, (c) a
  // refactor that HOMOGENIZES the 4 fields (all preserve, or
  // all clear) would silently break BOTH design intents at
  // once: making all-preserve would silently prevent users
  // from clearing heroName/preferredSite/timeZone (forcing
  // the frontend to add a dedicated clear endpoint),
  // making all-clear would silently wipe displayName every
  // time the user updates ANY other field (forcing the
  // frontend to ALWAYS resend displayName on every POST);
  // per-format regression vectors uniquely caught (NOT
  // caught by the 16981 7-field-shape pin which targets
  // RESPONSE SHAPE not PARTIAL-UPDATE SEMANTICS): (i)
  // refactor changing line 669 from `getOrElse(current.
  // profile.displayName)` to no getOrElse (i.e., displayName
  // = sanitizeDisplayName(displayName).getOrElse(None) or
  // similar) would silently CLEAR displayName on every
  // partial update -- the frontend would lose the user's
  // displayName the moment they change their timezone, (ii)
  // refactor adding `.getOrElse(current.profile.heroName)`
  // to line 670 would silently PRESERVE heroName on partial
  // updates -- breaking the documented user-controlled
  // clear semantic, (iii) refactor that switches the
  // semantics of `optionalString` parsing in
  // parseProfileUpdateRequest (e.g. from "missing/null/empty
  // -> None" to "missing -> currentValue, null -> None")
  // would silently subvert the per-field asymmetry by
  // distinguishing JSON-missing from JSON-null -- both of
  // which the current parser collapses to None; test
  // approach: register a user, POST profile with all 4
  // fields set (initial state), then POST partial-update
  // requests to demonstrate the documented asymmetry, then
  // verify the final state via /api/auth/me to confirm the
  // STORE-side state matches the response-side observation.
  test("/api/auth/profile PARTIAL-UPDATE ASYMMETRY contract: displayName is PRESERVED when omitted (line 669 getOrElse) while heroName + preferredSite + timeZone are CLEARED when omitted (lines 670-672 no-getOrElse) per PlatformUserAuth.scala lines 669-672's documented per-field asymmetric semantic -- complements the existing line 16981 7-field-shape pin by closing the PARTIAL-UPDATE SEMANTICS dimension") {
    withStaticSite { staticDir =>
      withUserStorePath { storePath =>
        withServer(staticDir, platformAuth = Some(PlatformUserAuth.Config(storePath = storePath))) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          // Helper: register user + capture session+CSRF for
          // subsequent profile updates
          val registerResp = postJson(
            s"$baseUri/api/auth/register",
            """{"email":"partial-update@example.com","password":"correct-horse-battery","displayName":"InitialName"}"""
          )
          assertEquals(registerResp.statusCode(), 201,
            clue = "user registration must succeed to drive the profile-update asymmetry test")
          val csrfToken = jsonBody(registerResp)("csrfToken").str
          val sessionCookieValue = sessionCookie(registerResp)

          def postProfile(body: String): HttpResponse[String] =
            httpClient.send(
              HttpRequest.newBuilder()
                .uri(URI.create(s"$baseUri/api/auth/profile"))
                .method("POST", HttpRequest.BodyPublishers.ofString(body))
                .header("Content-Type", "application/json")
                .header("Cookie", sessionCookieValue)
                .header("X-CSRF-Token", csrfToken)
                .build(),
              HttpResponse.BodyHandlers.ofString()
            )

          // (1) Initial setup: POST all 4 fields together
          val setupResp = postProfile(
            """{"displayName":"FullName","heroName":"HeroAlias","preferredSite":"PokerStars","timeZone":"America/New_York"}"""
          )
          assertEquals(setupResp.statusCode(), 200,
            clue = s"setup profile update with all 4 fields MUST return 200; got: ${setupResp.statusCode()}, body: ${setupResp.body()}")
          val setupBody = ujson.read(setupResp.body())
          val setupUser = setupBody("user").obj
          assertEquals(setupUser("displayName").str, "FullName",
            clue = "setup: displayName MUST be FullName after full-fields POST")
          assertEquals(setupUser("heroName").str, "HeroAlias",
            clue = "setup: heroName MUST be HeroAlias after full-fields POST")
          assertEquals(setupUser("preferredSite").str, "PokerStars",
            clue = "setup: preferredSite MUST be PokerStars after full-fields POST")
          assertEquals(setupUser("timeZone").str, "America/New_York",
            clue = "setup: timeZone MUST be America/New_York after full-fields POST")

          // (2) ASYMMETRY DEMO #1: POST {} (empty body) ->
          // displayName PRESERVED, heroName + preferredSite +
          // timeZone CLEARED. This is the documented
          // per-field-asymmetric behavior at lines 669-672.
          val emptyResp = postProfile("""{}""")
          assertEquals(emptyResp.statusCode(), 200,
            clue = s"empty-body profile POST MUST return 200; got: ${emptyResp.statusCode()}")
          val emptyBody = ujson.read(emptyResp.body())
          val emptyUser = emptyBody("user").obj
          assertEquals(emptyUser("displayName").str, "FullName",
            clue = s"ASYMMETRY: displayName MUST be PRESERVED when omitted from the request body per line 669's `getOrElse(current.profile.displayName)` semantic -- a refactor dropping the getOrElse would silently clear displayName on every partial update, breaking the documented `sticky displayName` contract; got: ${emptyUser("displayName")}")
          assertEquals(emptyUser.get("heroName"), Some(ujson.Null),
            clue = s"ASYMMETRY: heroName MUST be CLEARED (null) when omitted from the request body per line 670's no-getOrElse semantic -- a refactor adding `.getOrElse(current.profile.heroName)` would silently preserve heroName, breaking the documented user-controlled clear semantic; got: ${emptyUser.get("heroName")}")
          assertEquals(emptyUser.get("preferredSite"), Some(ujson.Null),
            clue = s"ASYMMETRY: preferredSite MUST be CLEARED when omitted per line 671's no-getOrElse semantic; got: ${emptyUser.get("preferredSite")}")
          assertEquals(emptyUser.get("timeZone"), Some(ujson.Null),
            clue = s"ASYMMETRY: timeZone MUST be CLEARED when omitted per line 672's no-getOrElse semantic; got: ${emptyUser.get("timeZone")}")

          // (3) Re-setup: POST all 4 fields again
          val resetResp = postProfile(
            """{"displayName":"FullName","heroName":"HeroAlias","preferredSite":"PokerStars","timeZone":"America/New_York"}"""
          )
          assertEquals(resetResp.statusCode(), 200,
            clue = "reset profile update MUST return 200")

          // (4) ASYMMETRY DEMO #2: POST {"heroName": "new"}
          // (single-field heroName update) -> displayName
          // PRESERVED (because omitted = preserve for
          // displayName), heroName=NewHero, preferredSite +
          // timeZone CLEARED (because omitted = clear for
          // them). This is the most operationally important
          // scenario: a user wants to ONLY update heroName
          // without touching anything else.
          val heroOnlyResp = postProfile("""{"heroName":"NewHero"}""")
          assertEquals(heroOnlyResp.statusCode(), 200,
            clue = "single-field heroName update MUST return 200")
          val heroOnlyUser = ujson.read(heroOnlyResp.body())("user").obj
          assertEquals(heroOnlyUser("displayName").str, "FullName",
            clue = s"ASYMMETRY DEMO #2: displayName MUST be PRESERVED after single-field heroName update (omitted from request -> preserve via line 669); got: ${heroOnlyUser("displayName")}")
          assertEquals(heroOnlyUser("heroName").str, "NewHero",
            clue = s"ASYMMETRY DEMO #2: heroName MUST be UPDATED to NewHero (explicit value in request); got: ${heroOnlyUser("heroName")}")
          assertEquals(heroOnlyUser.get("preferredSite"), Some(ujson.Null),
            clue = s"ASYMMETRY DEMO #2: preferredSite MUST be CLEARED after single-field heroName update (omitted from request -> clear via line 671's no-getOrElse) -- this is the silent-clear failure mode that would catch a frontend bug where the form sends partial updates without resending preferredSite; got: ${heroOnlyUser.get("preferredSite")}")
          assertEquals(heroOnlyUser.get("timeZone"), Some(ujson.Null),
            clue = s"ASYMMETRY DEMO #2: timeZone MUST be CLEARED after single-field heroName update; got: ${heroOnlyUser.get("timeZone")}")

          // (5) Re-setup
          val reset2Resp = postProfile(
            """{"displayName":"FullName","heroName":"HeroAlias","preferredSite":"PokerStars","timeZone":"America/New_York"}"""
          )
          assertEquals(reset2Resp.statusCode(), 200, clue = "reset #2 MUST return 200")

          // (6) ASYMMETRY DEMO #3: POST
          // {"displayName": "Updated"} (single-field
          // displayName update) -> displayName=Updated,
          // heroName + preferredSite + timeZone CLEARED.
          // This demonstrates the inverse of demo #2: when
          // the request EXPLICITLY sets displayName, it
          // overwrites; when it omits the other 3 fields,
          // they all CLEAR.
          val displayOnlyResp = postProfile("""{"displayName":"UpdatedName"}""")
          assertEquals(displayOnlyResp.statusCode(), 200,
            clue = "single-field displayName update MUST return 200")
          val displayOnlyUser = ujson.read(displayOnlyResp.body())("user").obj
          assertEquals(displayOnlyUser("displayName").str, "UpdatedName",
            clue = s"ASYMMETRY DEMO #3: displayName MUST be UPDATED to UpdatedName; got: ${displayOnlyUser("displayName")}")
          assertEquals(displayOnlyUser.get("heroName"), Some(ujson.Null),
            clue = s"ASYMMETRY DEMO #3: heroName MUST be CLEARED after single-field displayName update -- demonstrating that the asymmetry is INTRINSIC TO THE FIELD (not to the request shape); got: ${displayOnlyUser.get("heroName")}")
          assertEquals(displayOnlyUser.get("preferredSite"), Some(ujson.Null),
            clue = s"ASYMMETRY DEMO #3: preferredSite MUST be CLEARED; got: ${displayOnlyUser.get("preferredSite")}")
          assertEquals(displayOnlyUser.get("timeZone"), Some(ujson.Null),
            clue = s"ASYMMETRY DEMO #3: timeZone MUST be CLEARED; got: ${displayOnlyUser.get("timeZone")}")

          // (7) STORE-SIDE CROSS-CHECK: /api/auth/me reflects
          // the same state observed in the profile-update
          // response (catches a refactor that returns the
          // updated state in the response but persists a
          // different state to the store)
          val meResp = httpClient.send(
            HttpRequest.newBuilder()
              .uri(URI.create(s"$baseUri/api/auth/me"))
              .header("Cookie", sessionCookieValue)
              .GET()
              .build(),
            HttpResponse.BodyHandlers.ofString()
          )
          assertEquals(meResp.statusCode(), 200,
            clue = "/api/auth/me MUST return 200 to verify store-side state matches response-side observation")
          val meUser = ujson.read(meResp.body())("user").obj
          assertEquals(meUser("displayName").str, "UpdatedName",
            clue = s"STORE CROSS-CHECK: /api/auth/me displayName MUST equal the last-update value (the response state matches the store state); got: ${meUser("displayName")}")
          assertEquals(meUser.get("heroName"), Some(ujson.Null),
            clue = s"STORE CROSS-CHECK: /api/auth/me heroName MUST be null (cleared); got: ${meUser.get("heroName")}")
        }
      }
    }
  }

  // Pin the documented Retry-After: 5 FALLBACK contract for 503
  // responses at AuthStack.scala lines 572-573 -- the
  // RETRY-AFTER-FALLBACK pin verifies the documented RFC 7231
  // sec 6.6.4 defense-in-depth where EVERY 503 response from the
  // JsonHandler that doesn't already carry a Retry-After header
  // (i.e., the handler didn't compute a more-specific value)
  // gets the universal fallback "5" seconds added by the
  // post-fold Retry-After defense at lines 572-573:
  //     if response.status == 503 &&
  //        exchange.getResponseHeaders.getFirst("Retry-After") == null then
  //       exchange.getResponseHeaders.add("Retry-After", "5")
  // FIFTY-FIFTH per-emission-site SHAPE pin overall; the
  // RETRY-AFTER-FALLBACK contract is OPERATIONALLY CRITICAL
  // because: (a) RFC 7231 sec 6.6.4 explicitly says 503
  // responses SHOULD include Retry-After so clients back off
  // intelligently rather than guessing -- without the fallback,
  // any handler path that returns 503 via the Left-fold
  // (Left(503 -> "...")) would silently omit Retry-After
  // (the Left-fold at line 561 only produces the body, not
  // headers), forcing CDNs + clients to either retry
  // immediately (overloading the server) or back off
  // exponentially without coordination, (b) the documented
  // "5 seconds" fallback is the CONSERVATIVE default chosen
  // such that any caller can retry safely without overloading
  // even a marginally-recovering server -- a refactor changing
  // the value (e.g. to 1 or 60) would silently alter the
  // documented backoff behavior, (c) the documented design
  // explicitly REUSES the same fallback across ALL 503
  // emission sites (health/ready/analyze-submit/hall-submit
  // queue-full + draining) -- a refactor that moved the
  // fallback INSIDE per-handler logic would silently risk
  // skipping it on a new 503 path; per-format regression
  // vectors uniquely caught: (i) refactor dropping the lines
  // 572-573 fallback would silently OMIT Retry-After from any
  // 503 the handler didn't explicitly set (most/all current
  // paths), (ii) refactor changing the fallback value from
  // "5" to a different number would silently alter the
  // documented backoff cadence, (iii) refactor changing the
  // condition `response.status == 503` to broader (e.g.
  // `response.status >= 500`) would silently add Retry-After
  // to 5xx responses that don't document a retry contract
  // (500/501/504 etc.), (iv) refactor changing the
  // `getFirst("Retry-After") == null` guard to
  // `headers.contains("Retry-After")` (or similar) would
  // silently override handler-set Retry-After values; test
  // approach: trigger 3 distinct 503 paths (ready endpoint
  // while draining + analyze submit while draining + hall
  // submit while draining), verify ALL 3 carry Retry-After: 5
  // from the fallback, then verify NEGATIVE cases where 200
  // responses (ready when accepting + health always-200) do
  // NOT have Retry-After.
  test("503 responses MUST carry Retry-After: 5 fallback header per AuthStack.scala lines 572-573's documented RFC 7231 sec 6.6.4 defense-in-depth -- the UNIVERSAL fallback applies to ALL 503 emission sites (ready + analyze-submit + hall-submit while draining) where the handler didn't compute a more-specific value, while 200 responses do NOT inherit the fallback") {
    withStaticSite { staticDir =>
      val root = java.nio.file.Files.createTempDirectory("retry-after-fallback-")
      try
        val drainSignalFile = root.resolve("deploy-drain.signal")
        withServer(staticDir, drainSignalFile = Some(drainSignalFile)) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          // (0) PRE-DRAIN: verify 200 /api/ready does NOT
          // carry Retry-After (handler didn't set it + status
          // is not 503 so fallback doesn't fire)
          val preDrainReady = get(s"$baseUri/api/ready")
          assertEquals(preDrainReady.statusCode(), 200,
            clue = "pre-drain /api/ready MUST return 200 -- the test setup baseline")
          assertEquals(headerValue(preDrainReady, "Retry-After"), None,
            clue = s"PRE-DRAIN: 200 /api/ready MUST NOT carry Retry-After (the fallback at lines 572-573 ONLY fires on 503 responses, NEVER on 2xx); a refactor relaxing the `response.status == 503` guard would silently add Retry-After to 200 responses, confusing clients into delaying their next request unnecessarily; got: ${headerValue(preDrainReady, "Retry-After")}")

          // (0.5) PRE-DRAIN: 200 /api/health does NOT carry
          // Retry-After
          val preDrainHealth = get(s"$baseUri/api/health")
          assertEquals(preDrainHealth.statusCode(), 200,
            clue = "pre-drain /api/health MUST return 200")
          assertEquals(headerValue(preDrainHealth, "Retry-After"), None,
            clue = s"PRE-DRAIN: 200 /api/health MUST NOT carry Retry-After; got: ${headerValue(preDrainHealth, "Retry-After")}")

          // Flip to draining state via the drain signal file
          java.nio.file.Files.writeString(drainSignalFile, "draining", StandardCharsets.UTF_8)

          // (1) 503 /api/ready (draining) -> Retry-After: 5
          // fallback fires per lines 572-573
          val drainingReady = get(s"$baseUri/api/ready")
          assertEquals(drainingReady.statusCode(), 503,
            clue = s"draining /api/ready MUST return 503 to drive the Retry-After fallback test; got: ${drainingReady.statusCode()}")
          assertEquals(headerValue(drainingReady, "Retry-After"), Some("5"),
            clue = s"FALLBACK FIRES: 503 /api/ready MUST carry Retry-After: 5 per the AuthStack.scala lines 572-573 documented fallback -- a refactor dropping the fallback would silently omit Retry-After from this 503, violating RFC 7231 sec 6.6.4's SHOULD-clause + breaking client backoff coordination; got: ${headerValue(drainingReady, "Retry-After")}")

          // (2) 503 /api/analyze-hand-history submit (draining)
          // -> Retry-After: 5 fallback (this is the Left-fold
          // 503 path at HandHistoryReviewServerApi.scala line
          // 83's `Left(503 -> admissionRejectedMessage(...))`)
          val drainingAnalyze = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
          assertEquals(drainingAnalyze.statusCode(), 503,
            clue = s"draining /api/analyze-hand-history submit MUST return 503 to drive the Left-fold-path Retry-After fallback test; got: ${drainingAnalyze.statusCode()}")
          assertEquals(headerValue(drainingAnalyze, "Retry-After"), Some("5"),
            clue = s"FALLBACK FIRES (Left-fold): 503 analyze submission MUST carry Retry-After: 5 -- the Left-fold at AuthStack.scala line 561 only produces the body (1-field `{error}` shape), so the universal fallback at lines 572-573 is the ONLY source of Retry-After on this path; a refactor dropping the fallback would silently violate the RFC 7231 sec 6.6.4 SHOULD-clause for ALL analyze-submit 503 responses; got: ${headerValue(drainingAnalyze, "Retry-After")}")

          // (3) 503 /api/playing-hall submit (draining) ->
          // Retry-After: 5 fallback (symmetric with analyze
          // path at HandHistoryReviewServerApi.scala line 127)
          val drainingHall = postJson(s"$baseUri/api/playing-hall", validUploadPayload)
          assertEquals(drainingHall.statusCode(), 503,
            clue = s"draining /api/playing-hall submit MUST return 503 to drive the symmetric hall-path Retry-After fallback test; got: ${drainingHall.statusCode()}")
          assertEquals(headerValue(drainingHall, "Retry-After"), Some("5"),
            clue = s"FALLBACK FIRES (hall Left-fold): 503 hall submission MUST carry Retry-After: 5; got: ${headerValue(drainingHall, "Retry-After")}")

          // (4) UNIVERSAL FALLBACK VALUE CROSS-CHECK: ALL 3
          // 503 emission sites carry IDENTICAL Retry-After
          // values (the "5" constant from line 573)
          val retryAfterValues = Set(drainingReady, drainingAnalyze, drainingHall)
            .map(r => headerValue(r, "Retry-After"))
            .flatten
          assertEquals(retryAfterValues, Set("5"),
            clue = s"UNIVERSAL FALLBACK CROSS-CHECK: ALL 503 responses (ready + analyze-submit + hall-submit) MUST carry the SAME `5` Retry-After value per the lines 572-573 fallback's universal constant -- a refactor that diverged the value across emission sites (e.g. per-endpoint override of the fallback) would silently break the documented universal behavior + force operators to monitor each endpoint's Retry-After separately; got distinct values: $retryAfterValues")

          // (5) HEALTH ENDPOINT NEGATIVE CHECK: /api/health
          // remains 200 even while draining (it just reports
          // the draining state), so it does NOT trigger the
          // 503 fallback
          val drainingHealth = get(s"$baseUri/api/health")
          assertEquals(drainingHealth.statusCode(), 200,
            clue = s"draining /api/health MUST still return 200 (only /api/ready flips to 503 on drain); got: ${drainingHealth.statusCode()}")
          assertEquals(headerValue(drainingHealth, "Retry-After"), None,
            clue = s"NEGATIVE CHECK: draining 200 /api/health MUST NOT carry Retry-After (status != 503 so fallback doesn't fire); a refactor that broadened the fallback to 5xx OR added it unconditionally would silently emit Retry-After here; got: ${headerValue(drainingHealth, "Retry-After")}")
        }
      finally
        deleteRecursively(root)
    }
  }

  // Pin the documented Retry-After EXPLICIT-SET contract for 429
  // responses at AuthStack.scala lines 672-686 -- the
  // 429-EXPLICIT-SET pin verifies the documented SYMMETRIC
  // counterpart to the 503-fallback pin (7935924): where 503
  // emits a UNIVERSAL "5" via the post-fold fallback at lines
  // 572-573, 429 emits a COMPUTED value via the explicit
  // ensureWithinRateLimitJson set-call at line 676, the value
  // derived from the rate-limit window's remaining time at
  // RateLimit.scala line 73's `retryAfterMs = math.max(1L,
  // WindowMs - (now - existing.windowStartedAtMs))` formula.
  // FIFTY-SIXTH per-emission-site SHAPE pin overall; existing
  // line 14628 4-field 429-body-shape pin asserts the
  // retryAfterSeconds body field matches the Retry-After
  // header value, but the CROSS-CHECK between 429
  // (handler-explicit) and 503 (fallback) -- which documents
  // the SOURCE distinction between the two paths -- is
  // unpinned; the 429-EXPLICIT-SET contract is OPERATIONALLY
  // CRITICAL because: (a) the documented design intentionally
  // emits 429 Retry-After from the rate-limit window's
  // remaining time (NOT the generic 5-second fallback) so
  // clients can compute the optimal backoff: hitting the rate
  // limit at the start of a 60-second window means waiting
  // 60 seconds, hitting it 50 seconds in means waiting 10
  // seconds -- a refactor that emitted the generic "5"
  // fallback would silently flatten this signal, causing all
  // 429 clients to retry in a thundering herd, (b) the
  // SYMMETRIC pin pair (THIS commit 429 + 7935924 503)
  // documents the FULL Retry-After source matrix: 429 is
  // always handler-explicit (line 676 unconditional set), 503
  // is always fallback (handlers don't set their own per the
  // current code), (c) a refactor that DROPPED the line 676
  // explicit set on 429 would silently FALL THROUGH to the
  // 503 fallback at lines 572-573 -- but only if the response
  // status were ALSO 503, which would silently shift the
  // contract entirely; per-format regression vectors uniquely
  // caught (NOT caught by the 14628 body-shape pin which
  // verifies retryAfterSeconds body field == Retry-After
  // header value but not whether the value is computed-vs-
  // fallback): (i) refactor changing line 676 from `set(
  // "Retry-After", retryAfter)` to a hardcoded "5" would
  // silently collapse the 429 path into the 503 fallback
  // contract -- the 14628 pin would still PASS (body field
  // == header value) but the OPERATIONAL signal would be
  // lost, (ii) refactor that changes the
  // retryAfterMs formula at RateLimit.scala line 73 (e.g. to
  // `WindowMs` unconditionally instead of remaining-time)
  // would silently emit a CONSTANT 60-second Retry-After even
  // for clients who hit the limit late in the window -- a
  // less-thundering-herd-resistant scheme, (iii) refactor
  // that removed the math.max(1L, ...) floor at RateLimit.
  // scala line 73 would silently allow Retry-After: 0 (or
  // negative when the window expired between rejection and
  // emission) -- breaking RFC 7231 sec 7.1.3 which requires
  // Retry-After be a positive HTTP-date or delta-seconds; test
  // approach: set rateLimitSubmitsPerMinute=1 + drain signal
  // file, submit once (202 consumes the slot), submit again
  // (429 + COMPUTED Retry-After), activate drain signal,
  // /api/ready (503 + FALLBACK Retry-After), then cross-check
  // the two distinct Retry-After values originate from
  // distinct paths.
  test("429 vs 503 Retry-After SOURCE DISTINCTION: 429 emits a COMPUTED Retry-After from the rate-limit window's remaining time per AuthStack.scala line 676's explicit set + RateLimit.scala line 73's retryAfterMs formula, while 503 emits the universal `5` fallback per AuthStack.scala lines 572-573 -- the SYMMETRIC pin closes the SOURCE dimension complementing 7935924's 503-fallback pin + 14628's 429-body-shape pin") {
    withStaticSite { staticDir =>
      val root = java.nio.file.Files.createTempDirectory("retry-after-source-")
      try
        val drainSignalFile = root.resolve("deploy-drain.signal")
        withServer(
          staticDir,
          rateLimitSubmitsPerMinute = 1,
          rateLimitStatusPerMinute = 0,
          drainSignalFile = Some(drainSignalFile)
        ) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          // (1) Submit 1 -> 202 (consumes the 1/minute slot)
          val accepted = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
          assertEquals(accepted.statusCode(), 202,
            clue = "first submit MUST 202 to consume the rateLimitSubmitsPerMinute=1 slot before driving the 429 path")

          // (2) Submit 2 -> 429 with COMPUTED Retry-After
          val rateLimited = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
          assertEquals(rateLimited.statusCode(), 429,
            clue = "second submit MUST 429 to drive the explicit-set Retry-After test")
          val rateLimitedRetryAfter = headerValue(rateLimited, "Retry-After")
            .getOrElse(fail("429 response MUST carry Retry-After per AuthStack.scala line 676's `set(\"Retry-After\", retryAfter)`"))

          // (3) Activate drain signal -> /api/ready 503 with
          // FALLBACK Retry-After: 5
          java.nio.file.Files.writeString(drainSignalFile, "draining", StandardCharsets.UTF_8)
          val drainingReady = get(s"$baseUri/api/ready")
          assertEquals(drainingReady.statusCode(), 503,
            clue = "draining /api/ready MUST 503 to drive the fallback Retry-After test")
          val drainingReadyRetryAfter = headerValue(drainingReady, "Retry-After")
            .getOrElse(fail("503 /api/ready MUST carry Retry-After: 5 fallback per AuthStack.scala lines 572-573"))

          // (4) 503 Retry-After IS the fallback `5` constant
          assertEquals(drainingReadyRetryAfter, "5",
            clue = s"503 Retry-After MUST be `5` per AuthStack.scala lines 572-573 fallback -- the documented universal constant; got: $drainingReadyRetryAfter")

          // (5) 429 Retry-After is a POSITIVE INTEGER (parseable)
          // per RFC 7231 sec 7.1.3's delta-seconds requirement
          val rateLimitedRetryAfterInt = scala.util.Try(rateLimitedRetryAfter.toInt).getOrElse(
            fail(s"429 Retry-After MUST be parseable as integer per RFC 7231 sec 7.1.3 delta-seconds form; got: $rateLimitedRetryAfter")
          )
          assert(rateLimitedRetryAfterInt > 0,
            clue = s"429 Retry-After MUST be > 0 per RateLimit.scala line 73's `math.max(1L, ...)` floor -- a refactor removing the floor could silently allow 0 or negative when the window expired between rejection and emission, violating RFC 7231 sec 7.1.3; got: $rateLimitedRetryAfterInt")

          // (6) 429 Retry-After ≠ 503 Retry-After -- the
          // SOURCE DISTINCTION assertion that catches a
          // refactor collapsing the explicit-set path into
          // the fallback (e.g. hardcoding line 676 to "5")
          assertNotEquals(rateLimitedRetryAfter, drainingReadyRetryAfter,
            clue = s"429 Retry-After ($rateLimitedRetryAfter) MUST differ from 503 Retry-After ($drainingReadyRetryAfter) -- the SOURCE distinction proves: 429 is computed from rate-limit-window remaining time (RateLimit.scala line 73), 503 is the fallback `5` constant (AuthStack.scala line 573); a refactor that hardcoded 429 to emit `5` would silently flatten the operational signal, causing all 429 clients to retry in a thundering herd at the 5-second mark")

          // (7) 429 Retry-After value is REASONABLE for the
          // rate-limit window (1-60 seconds for a 1/minute
          // window struck at submit time -- catches a refactor
          // that emitted a wildly different value like 0 or
          // 3600)
          assert(rateLimitedRetryAfterInt >= 1 && rateLimitedRetryAfterInt <= 61,
            clue = s"429 Retry-After MUST be within 1..61 seconds for a rateLimitSubmitsPerMinute=1 window struck at submit time per RateLimit.scala line 73's `retryAfterMs = WindowMs - elapsed` formula + the line 840 `retryAfterSeconds` ceiling -- a refactor changing the window or formula would silently shift the value out of this band; got: $rateLimitedRetryAfterInt")

          // (8) 429 Retry-After > 5 -- the explicit-set value
          // is strictly GREATER than the 503 fallback. This
          // catches a subtle refactor that changes the 429
          // path to use a CONSTANT (e.g. `5` for "simplify")
          // which would silently match the 503 fallback even
          // though the SOURCES differ.
          assert(rateLimitedRetryAfterInt > 5,
            clue = s"429 Retry-After MUST be > 5 (the 503 fallback constant) -- the rate-limit window for rateLimitSubmitsPerMinute=1 is 60 seconds, so the remaining time at second submit is ≥55s per the formula; if the value collapsed to exactly 5, the SOURCE distinction would be operationally invisible (clients couldn't tell which path emitted the value); got: $rateLimitedRetryAfterInt")

          // (9) CROSS-CHECK with 429 body: the documented
          // explicit-set path emits the SAME value on BOTH
          // header AND body.retryAfterSeconds (AuthStack.scala
          // line 682-684 + 676 share the `retryAfter`
          // variable). This is the symmetric counterpart to
          // the 503 fallback path which doesn't add a body
          // field (the 1-field {error} shape).
          val rateLimitedBody = jsonBody(rateLimited)
          val rateLimitedBodyRetryAfter = rateLimitedBody("retryAfterSeconds").num.toInt
          assertEquals(rateLimitedBodyRetryAfter, rateLimitedRetryAfterInt,
            clue = s"429 body.retryAfterSeconds MUST EQUAL header Retry-After per AuthStack.scala line 676 + 682-684's SHARED `retryAfter` variable -- a refactor that diverged the two emissions would silently produce inconsistent backoff hints; got header=$rateLimitedRetryAfterInt, body=$rateLimitedBodyRetryAfter")
        }
      finally
        deleteRecursively(root)
    }
  }

  // Pin the documented CROSS-BUCKET 429 INDEPENDENCE contract
  // at RateLimit.scala line 59 (`s"${bucket.id}|$clientKey"`)
  // -- the CROSS-BUCKET-INDEPENDENCE pin verifies the
  // documented per-bucket state isolation where each rate-
  // limit bucket (Submit, JobStatus, Auth) maintains its OWN
  // window state keyed by `<bucket-id>|<client-key>`, NOT a
  // shared client-keyed counter that would deplete across
  // buckets. FIFTY-SEVENTH per-emission-site SHAPE pin
  // overall; existing per-bucket tests at lines 20176/20191/
  // 20224 each test ONE bucket in isolation (with the other
  // two buckets disabled via *PerMinute=0), but the
  // CROSS-BUCKET INDEPENDENCE invariant -- which verifies
  // that depleting ONE bucket does NOT consume slots in the
  // OTHER buckets -- requires all 3 buckets to be
  // simultaneously enabled in a single test; the CROSS-BUCKET
  // INDEPENDENCE contract is OPERATIONALLY CRITICAL because:
  // (a) the documented design ensures that a hostile client
  // depleting one rate-limit bucket (e.g., flooding /api/
  // analyze-hand-history submissions) CANNOT silently break
  // their own access to OTHER endpoints (status polling
  // becomes unavailable too) -- a refactor that shared the
  // window state across buckets would cause this collateral
  // damage that legitimate users would experience as random
  // 429s on endpoints they didn't even hit, (b) per-bucket
  // independence enables differential operator control: the
  // Submit bucket can be tightened (e.g., 6/minute) without
  // affecting JobStatus polling (240/minute) or Auth attempts
  // (10/minute) -- a refactor losing the per-bucket isolation
  // would force operators to choose the lowest-common-
  // denominator value, hamstringing legitimate-traffic
  // throughput, (c) RateLimit.scala line 59's key construction
  // `s"${bucket.id}|$clientKey"` is the SOURCE OF TRUTH for
  // the per-bucket isolation -- a refactor that dropped the
  // bucket prefix (e.g., key = clientKey only) would silently
  // collapse all 3 buckets into one shared counter; per-format
  // regression vectors uniquely caught (NOT caught by the
  // individual per-bucket tests at lines 20176/20191/20224
  // which each disable the other two buckets): (i) refactor
  // dropping the bucket prefix from the line 59 key would
  // silently make all 3 buckets share one counter -- the
  // individual tests would still PASS (each tests only their
  // own bucket at limit=1), but cross-bucket independence
  // would be broken, (ii) refactor that double-counted the
  // bucket prefix (e.g. using `s"${bucket.id}|${bucket.id}|
  // $clientKey"`) would silently still isolate by bucket BUT
  // change the key shape (catches via the rateLimitBucket
  // emission assertion which uses the documented enum value
  // `submit`/`job-status`/`auth`), (iii) refactor that
  // accidentally re-used the rate-limit state object across
  // bucket lookups (e.g., a shared mutable map without bucket
  // namespacing) would silently break independence; test
  // approach: configure a single server with ALL 3 buckets
  // enabled at limit=1 + platformAuth + immediateBackend (so
  // /api/auth/* + status polling are reachable), exercise
  // each bucket in turn proving (a) the FIRST request to a
  // new bucket SUCCEEDS even after OTHER buckets are
  // exhausted (independence) + (b) the SECOND request to the
  // SAME bucket is 429 (bucket itself is enforced), and (c)
  // each 429 has its own rateLimitBucket id.
  test("CROSS-BUCKET 429 INDEPENDENCE: each rate-limit bucket (Submit / JobStatus / Auth) maintains its OWN window state per RateLimit.scala line 59's `s\"${bucket.id}|$$clientKey\"` key construction -- depleting one bucket does NOT consume slots in the others, and each 429 emits its own bucket-specific rateLimitBucket id from the documented enum") {
    withStaticSite { staticDir =>
      withUserStorePath { storePath =>
        withServer(
          staticDir,
          platformAuth = Some(PlatformUserAuth.Config(storePath = storePath)),
          rateLimitSubmitsPerMinute = 1,
          rateLimitStatusPerMinute = 1,
          rateLimitAuthPerMinute = 1
        ) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          // (1) Register a user (consumes Auth bucket slot
          // 1/1; we'll separately exhaust it below by hitting
          // login). But before that, let's verify that
          // registration succeeds even though we'll exercise
          // other buckets next -- proving the buckets ARE
          // initially fresh.
          val registerResp = postJson(
            s"$baseUri/api/auth/register",
            """{"email":"cross-bucket@example.com","password":"correct-horse-battery","displayName":"X"}"""
          )
          assertEquals(registerResp.statusCode(), 201,
            clue = s"register MUST 201 to consume the Auth bucket slot 1/1; got: ${registerResp.statusCode()}")
          val sessionCookieValue = sessionCookie(registerResp)
          val csrfToken = jsonBody(registerResp)("csrfToken").str

          // (2) Submit POST 1 -> 202 (Submit slot 1/1).
          // PROVES: Auth's slot exhaustion (next request to
          // /api/auth/* will 429) does NOT consume the Submit
          // slot. Submit is fresh.
          val submitHeaders = Map("Cookie" -> sessionCookieValue, "X-CSRF-Token" -> csrfToken)
          val submit1 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, submitHeaders)
          assertEquals(submit1.statusCode(), 202,
            clue = s"submit 1 MUST 202 -- the Submit bucket starts fresh even though Auth was just consumed; INDEPENDENCE proof #1; got: ${submit1.statusCode()}, body: ${submit1.body()}")
          val statusUrl = s"$baseUri${jsonBody(submit1)("statusUrl").str}"

          // (3) Submit POST 2 -> 429 bucket=submit (Submit
          // exhausted)
          val submit2 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, submitHeaders)
          assertEquals(submit2.statusCode(), 429,
            clue = s"submit 2 MUST 429 -- Submit bucket exhausted at 1/1; got: ${submit2.statusCode()}")
          val submitBucketBody = jsonBody(submit2)
          assertEquals(submitBucketBody("rateLimitBucket").str, "submit",
            clue = s"Submit-bucket 429 MUST identify rateLimitBucket=`submit` per RateLimitBucket.Submit.id; got: ${submitBucketBody("rateLimitBucket").str}")

          // (4) GET status URL 1 -> some-status (JobStatus
          // slot 1/1 used). PROVES: Submit's exhaustion did
          // NOT consume the JobStatus slot. JobStatus is fresh.
          val status1 = get(statusUrl, submitHeaders)
          assert(status1.statusCode() == 200 || status1.statusCode() == 202,
            clue = s"status 1 MUST be 200 or 202 -- the JobStatus bucket starts fresh even though Submit was just exhausted; INDEPENDENCE proof #2; got: ${status1.statusCode()}")

          // (5) GET status URL 2 -> 429 bucket=job-status
          // (JobStatus exhausted)
          val status2 = get(statusUrl, submitHeaders)
          assertEquals(status2.statusCode(), 429,
            clue = s"status 2 MUST 429 -- JobStatus bucket exhausted at 1/1; got: ${status2.statusCode()}")
          val statusBucketBody = jsonBody(status2)
          assertEquals(statusBucketBody("rateLimitBucket").str, "job-status",
            clue = s"JobStatus-bucket 429 MUST identify rateLimitBucket=`job-status` per RateLimitBucket.JobStatus.id; got: ${statusBucketBody("rateLimitBucket").str}")

          // (6) POST /api/auth/login 1 -> some-status
          // (Auth slot already 1/1 used by registration at
          // step (1)). So login 1 here ALREADY hits the
          // exhausted Auth bucket -> 429 bucket=auth.
          // PROVES: Submit + JobStatus exhaustion did NOT
          // affect the Auth bucket's state -- the previously
          // consumed slot (from register) is still the
          // governing state for Auth.
          val login1 = postJson(s"$baseUri/api/auth/login",
            """{"email":"cross-bucket@example.com","password":"correct-horse-battery"}""")
          assertEquals(login1.statusCode(), 429,
            clue = s"login MUST 429 -- Auth bucket was already exhausted at step (1) via register, and Submit + JobStatus exhaustion did NOT alter the Auth bucket's state; INDEPENDENCE proof #3 -- if buckets shared state, the Auth slot would have been INCREMENTED past 1/1 by the Submit + JobStatus consumption above, but it was NOT (counter is per-bucket); got: ${login1.statusCode()}")
          val authBucketBody = jsonBody(login1)
          assertEquals(authBucketBody("rateLimitBucket").str, "auth",
            clue = s"Auth-bucket 429 MUST identify rateLimitBucket=`auth` per RateLimitBucket.Auth.id; got: ${authBucketBody("rateLimitBucket").str}")

          // (7) CROSS-CHECK: ALL 3 buckets emitted 429s with
          // DISTINCT rateLimitBucket ids -- the CLOSED SET
          // {submit, job-status, auth} matches the documented
          // RateLimitBucket enum values per RateLimit.scala
          // lines 14-25.
          val bucketIds = Set(
            submitBucketBody("rateLimitBucket").str,
            statusBucketBody("rateLimitBucket").str,
            authBucketBody("rateLimitBucket").str
          )
          val expectedBuckets = Set("submit", "job-status", "auth")
          assertEquals(bucketIds, expectedBuckets,
            clue = s"the 3 distinct 429 responses MUST emit ALL 3 documented bucket ids per the RateLimitBucket enum (submit + job-status + auth) -- the CROSS-BUCKET INDEPENDENCE proof shows each bucket has its own state AND each 429 correctly identifies its source bucket; got=$bucketIds, expected=$expectedBuckets")

          // (8) CROSS-BUCKET DISTINCT-CLIENT-CHECK: depleting
          // these 3 buckets did NOT consume slots in any OTHER
          // bucket (since there are only 3 buckets in the
          // documented enum). Defense-in-depth: verify that
          // unrelated probe endpoints (which don't use rate
          // limiting) still work.
          val healthResp = get(s"$baseUri/api/health")
          assertEquals(healthResp.statusCode(), 200,
            clue = s"unrelated probe /api/health MUST still 200 after ALL 3 rate-limit buckets are exhausted -- /api/health is NOT rate-limited per HandHistoryReviewServerRuntime.scala line 76 (no rateLimiter passed) and remains reachable as a documented health-probe invariant; got: ${healthResp.statusCode()}")
          val readyResp = get(s"$baseUri/api/ready")
          assertEquals(readyResp.statusCode(), 200,
            clue = s"unrelated probe /api/ready MUST still 200 after ALL 3 buckets exhausted -- /api/ready is NOT rate-limited per HandHistoryReviewServerRuntime.scala line 121; got: ${readyResp.statusCode()}")
        }
      }
    }
  }

  // Pin the documented CROSS-CLIENT-IP 429 ISOLATION contract
  // at RateLimit.scala line 59's `s"${bucket.id}|$clientKey"`
  // key construction -- the CROSS-CLIENT-ISOLATION pin verifies
  // the documented per-client-key state isolation where two
  // distinct client IPs (different X-Real-IP values) maintain
  // INDEPENDENT rate-limit windows within the SAME bucket: one
  // client depleting its slot does NOT consume the OTHER
  // client's slot. FIFTY-EIGHTH per-emission-site SHAPE pin
  // overall; existing line 5566 test verifies SAME-CLIENT
  // header-keyed enforcement (2 submissions from the SAME
  // X-Real-IP both go through the same client key), but the
  // CROSS-CLIENT-IP INDEPENDENCE invariant -- which verifies
  // that DIFFERENT X-Real-IP values produce DIFFERENT client
  // keys with independent counters -- requires TWO distinct
  // client IPs in a single test; the CROSS-CLIENT-ISOLATION
  // contract is OPERATIONALLY CRITICAL because: (a) the
  // documented design ensures that one hostile client cannot
  // DoS legitimate users by exhausting a shared counter --
  // each client has their own quota, so flooders only DoS
  // themselves, (b) a refactor that dropped the client-key
  // portion from the line 59 key would silently make ALL
  // clients share ONE bucket-wide counter, transforming a
  // per-client rate limit into a global rate limit (e.g.,
  // 1/minute would mean only 1 user globally per minute can
  // submit, regardless of how many users there are), (c) the
  // SYMMETRIC pin pair (THIS commit cross-CLIENT + bd92a11
  // cross-BUCKET) documents the FULL isolation matrix: each
  // (bucket, client-key) pair has its OWN window state,
  // requiring BOTH dimensions in the line 59 key
  // construction; per-format regression vectors uniquely
  // caught (NOT caught by the 5566 single-client header-keyed
  // test OR the per-bucket pins): (i) refactor dropping the
  // clientKey portion from the line 59 key (e.g., `key =
  // bucket.id` only) would silently collapse all clients into
  // a single shared counter -- the 5566 test would still
  // PASS (single client, two requests, second one 429) but
  // cross-client independence would be broken, (ii) refactor
  // that accidentally re-keyed by a CONSTANT instead of the
  // resolved clientKey (e.g., always using "default" or null)
  // would silently collapse the per-client isolation while
  // preserving per-bucket isolation; test approach:
  // configure rateLimitClientIpHeader=Some("X-Real-IP") +
  // rateLimitSubmitsPerMinute=1 (loopback peer is
  // automatically trusted per the test framework), submit
  // from Client A's X-Real-IP value (202), submit from Client
  // A AGAIN (429 -- Client A exhausted), submit from Client
  // B's DIFFERENT X-Real-IP value (202 -- INDEPENDENCE proof
  // that Client A's exhaustion did NOT consume Client B's
  // slot), submit from Client B AGAIN (429 -- Client B
  // exhausted), cross-check both 429s identify bucket=submit
  // but represent independent counter exhaustion.
  test("CROSS-CLIENT-IP 429 ISOLATION: two distinct X-Real-IP values produce INDEPENDENT rate-limit windows within the SAME bucket per RateLimit.scala line 59's `s\"${bucket.id}|$$clientKey\"` key construction -- depleting one client's slot does NOT consume the OTHER client's slot, proving the per-client-key isolation that enables per-client quotas (vs a global shared counter)") {
    withStaticSite { staticDir =>
      withServer(
        staticDir,
        rateLimitSubmitsPerMinute = 1,
        rateLimitStatusPerMinute = 0,
        rateLimitClientIpHeader = Some("X-Real-IP")
      ) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        val clientAHeaders = Map("X-Real-IP" -> "203.0.113.10")
        val clientBHeaders = Map("X-Real-IP" -> "203.0.113.20")

        // (1) Client A submit 1 -> 202 (Client A slot 1/1 used)
        val a1 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, clientAHeaders)
        assertEquals(a1.statusCode(), 202,
          clue = s"Client A's first submit MUST 202 to consume slot 1/1; got: ${a1.statusCode()}")

        // (2) Client A submit 2 -> 429 (Client A exhausted).
        // Sanity check: the SAME-CLIENT enforcement still
        // works (catches a refactor that BROKE per-client
        // enforcement entirely).
        val a2 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, clientAHeaders)
        assertEquals(a2.statusCode(), 429,
          clue = s"Client A's second submit MUST 429 -- Client A bucket exhausted at 1/1; got: ${a2.statusCode()}")
        val a2Body = jsonBody(a2)
        assertEquals(a2Body("rateLimitBucket").str, "submit",
          clue = s"Client A's 429 MUST identify rateLimitBucket=submit; got: ${a2Body("rateLimitBucket").str}")

        // (3) Client B submit 1 -> 202 (Client B slot 1/1
        // used). THE UNIQUE INDEPENDENCE SIGNAL: if the rate-
        // limit state were SHARED across clients (e.g., the
        // line 59 key dropped the clientKey portion), Client
        // B's first submission would inherit Client A's
        // exhausted counter and return 429 instead of 202.
        val b1 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, clientBHeaders)
        assertEquals(b1.statusCode(), 202,
          clue = s"INDEPENDENCE PROOF: Client B's first submit MUST 202 even though Client A is exhausted -- the documented per-client-key isolation at RateLimit.scala line 59 ensures Client B has its own fresh window; a refactor dropping the clientKey portion from the line 59 key construction would collapse all clients into a shared counter, silently failing this assertion; got: ${b1.statusCode()}, body: ${b1.body()}")

        // (4) Client B submit 2 -> 429 (Client B exhausted).
        // Confirms Client B's bucket is ENFORCED, not just
        // SHARED-but-empty.
        val b2 = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, clientBHeaders)
        assertEquals(b2.statusCode(), 429,
          clue = s"Client B's second submit MUST 429 -- Client B bucket exhausted at 1/1 (its OWN window, independent of Client A's); got: ${b2.statusCode()}")
        val b2Body = jsonBody(b2)
        assertEquals(b2Body("rateLimitBucket").str, "submit",
          clue = s"Client B's 429 MUST identify rateLimitBucket=submit (same bucket id as Client A's 429, but independent counter); got: ${b2Body("rateLimitBucket").str}")

        // (5) CROSS-CHECK: BOTH 429 responses identify the
        // SAME bucket id (submit) -- proving that the
        // independence is per-CLIENT, NOT per-BUCKET. Both
        // clients are hitting the SAME bucket; the isolation
        // is along the OTHER dimension of the line 59 key.
        assertEquals(a2Body("rateLimitBucket").str, b2Body("rateLimitBucket").str,
          clue = s"BOTH 429s MUST identify the SAME bucket id (`submit`) -- the per-client isolation is along the clientKey dimension of the line 59 key `bucket.id|clientKey`, NOT the bucket.id dimension; got A=${a2Body("rateLimitBucket").str}, B=${b2Body("rateLimitBucket").str}")

        // (6) CROSS-CHECK: BOTH 429s identify the SAME
        // limitPerMinute=1 (both have the same per-client
        // quota of 1/minute, NOT a shared global quota)
        assertEquals(a2Body("limitPerMinute").num.toInt, b2Body("limitPerMinute").num.toInt,
          clue = s"BOTH 429s MUST identify limitPerMinute=1 -- the documented per-client quota is the SAME across clients (1/minute each), NOT a shared global cap; got A=${a2Body("limitPerMinute").num.toInt}, B=${b2Body("limitPerMinute").num.toInt}")
        assertEquals(a2Body("limitPerMinute").num.toInt, 1,
          clue = s"limitPerMinute MUST be 1 per the test's rateLimitSubmitsPerMinute=1 configuration; got: ${a2Body("limitPerMinute").num.toInt}")

        // (7) NEGATIVE CHECK: Client A's exhaustion is
        // PERSISTENT (re-hitting after Client B's window also
        // gets 429). Catches a refactor that would
        // accidentally clear Client A's counter when Client
        // B's window got created.
        val aRetry = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload, clientAHeaders)
        assertEquals(aRetry.statusCode(), 429,
          clue = s"PERSISTENCE: Client A's window is still exhausted after Client B's window was created/exhausted -- the per-client states are persistent across other clients' activity; got: ${aRetry.statusCode()}")
      }
    }
  }

  // Pin the documented profile-field MAX-LENGTH BOUNDARY
  // contract at PlatformUserAuth.scala line 1140-1141's
  // `sanitizeOptionalField` length check
  // (`if value.length > maxLength then throw new
  // IllegalArgumentException(s"$label must be at most
  // $maxLength characters")`) -- the MAX-LENGTH-BOUNDARY pin
  // verifies the documented per-field length caps where each
  // profile field has a distinct documented maximum:
  // displayName=96 (line 1136 sanitizeDisplayName), heroName=64
  // (line 670), preferredSite=32 (line 671), timeZone=64
  // (line 672); a value AT the cap is accepted (200), a value
  // ONE char OVER the cap is rejected (400) with the
  // documented `<label> must be at most <N> characters`
  // message. FIFTY-NINTH per-emission-site SHAPE pin overall;
  // the MAX-LENGTH-BOUNDARY contract is OPERATIONALLY CRITICAL
  // because: (a) the per-field caps are the documented defense
  // against unbounded-storage attacks where a hostile user
  // inflates the persisted user-store JSON with megabyte-sized
  // profile fields -- a refactor dropping or widening a cap
  // would silently reopen the storage-amplification vector,
  // (b) each field's cap is INDEPENDENTLY chosen for its
  // semantic role (displayName=96 for full names, heroName=64
  // for poker aliases, preferredSite=32 for site names,
  // timeZone=64 for IANA tz identifiers) -- a refactor that
  // HOMOGENIZED the caps (e.g. all 64) would silently change
  // the validation envelope for displayName (truncating long
  // legal names) and preferredSite (allowing 2x-longer site
  // strings), (c) the boundary is INCLUSIVE at the cap
  // (value.length > maxLength rejects, so == maxLength is
  // accepted) -- a refactor flipping to `>=` would silently
  // reject legal max-length values, an off-by-one that the
  // exact-boundary test catches; per-format regression
  // vectors uniquely caught: (i) refactor changing any per-
  // field cap constant would silently shift the boundary --
  // the exact-cap + cap+1 pair brackets each field's specific
  // value, (ii) refactor changing the comparison from `>` to
  // `>=` would silently reject the at-cap value (off-by-one),
  // (iii) refactor changing the error-message format would
  // silently break clients/UIs that surface the documented
  // `must be at most N characters` text to users; test
  // approach: register a user, then for EACH of the 4 fields
  // POST a value at EXACTLY the documented cap (expect 200) +
  // a value at cap+1 (expect 400 with the documented per-
  // field message), confirming both the boundary value + the
  // per-field cap constant.
  test("profile-field MAX-LENGTH BOUNDARY contract: each field accepts a value AT its documented cap (displayName=96, heroName=64, preferredSite=32, timeZone=64) and rejects a value ONE char OVER with the documented `<label> must be at most <N> characters` 400 error per PlatformUserAuth.scala lines 1140-1141's sanitizeOptionalField length check") {
    withStaticSite { staticDir =>
      withUserStorePath { storePath =>
        withServer(staticDir, platformAuth = Some(PlatformUserAuth.Config(storePath = storePath))) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          val registerResp = postJson(
            s"$baseUri/api/auth/register",
            """{"email":"maxlen@example.com","password":"correct-horse-battery","displayName":"X"}"""
          )
          assertEquals(registerResp.statusCode(), 201,
            clue = "register MUST 201 to drive the profile max-length boundary test")
          val csrfToken = jsonBody(registerResp)("csrfToken").str
          val sessionCookieValue = sessionCookie(registerResp)

          def postProfile(body: String): HttpResponse[String] =
            httpClient.send(
              HttpRequest.newBuilder()
                .uri(URI.create(s"$baseUri/api/auth/profile"))
                .method("POST", HttpRequest.BodyPublishers.ofString(body))
                .header("Content-Type", "application/json")
                .header("Cookie", sessionCookieValue)
                .header("X-CSRF-Token", csrfToken)
                .build(),
              HttpResponse.BodyHandlers.ofString()
            )

          // The 4 documented per-field caps. Each tuple is
          // (jsonKey, label-in-error-message, maxLength).
          val fields = Vector(
            ("displayName", "displayName", 96),
            ("heroName", "heroName", 64),
            ("preferredSite", "preferredSite", 32),
            ("timeZone", "timeZone", 64)
          )

          fields.foreach { case (jsonKey, label, maxLength) =>
            // (a) value AT the cap -> 200 (the boundary is
            // INCLUSIVE: value.length > maxLength rejects, so
            // == maxLength is accepted)
            val atCapValue = "a" * maxLength
            val atCapResp = postProfile(s"""{"$jsonKey":"$atCapValue"}""")
            assertEquals(atCapResp.statusCode(), 200,
              clue = s"$jsonKey at EXACTLY the documented cap ($maxLength chars) MUST be accepted (200) per PlatformUserAuth.scala line 1140's `value.length > maxLength` exclusive-upper comparison -- a refactor flipping to `>=` would silently reject this legal at-cap value (off-by-one); got: ${atCapResp.statusCode()}, body: ${atCapResp.body()}")
            // CROSS-CHECK: the at-cap value round-trips in the
            // response (proving it was actually stored, not
            // silently truncated)
            val atCapUser = ujson.read(atCapResp.body())("user").obj
            assertEquals(atCapUser(jsonKey).str.length, maxLength,
              clue = s"$jsonKey at-cap value MUST round-trip at full $maxLength-char length (NOT silently truncated) -- a refactor that truncated instead of rejecting would silently corrupt user data; got length: ${atCapUser(jsonKey).str.length}")

            // (b) value ONE char OVER the cap -> 400 with the
            // documented per-field error message
            val overCapValue = "a" * (maxLength + 1)
            val overCapResp = postProfile(s"""{"$jsonKey":"$overCapValue"}""")
            assertEquals(overCapResp.statusCode(), 400,
              clue = s"$jsonKey at cap+1 (${maxLength + 1} chars) MUST be rejected (400) per PlatformUserAuth.scala line 1141's IllegalArgumentException -> AuthStack.scala line 235's `400 -> error` mapping; a refactor dropping/widening the cap would silently accept this over-cap value, reopening the storage-amplification vector; got: ${overCapResp.statusCode()}, body: ${overCapResp.body()}")
            val overCapBody = jsonBody(overCapResp)
            // The error response is the universal 1-field
            // {error} shape per the AuthStack Left-fold
            assertEquals(overCapBody.obj.keys.toSet, Set("error"),
              clue = s"$jsonKey over-cap 400 MUST emit the universal 1-field {error} shape per AuthStack.scala line 561's Left-fold; got fields: ${overCapBody.obj.keys.toVector.sorted.mkString(", ")}")
            // The documented error message format:
            // `<label> must be at most <N> characters`
            val expectedMessage = s"$label must be at most $maxLength characters"
            assertEquals(overCapBody("error").str, expectedMessage,
              clue = s"$jsonKey over-cap 400 error message MUST be EXACTLY `$expectedMessage` per PlatformUserAuth.scala line 1141's `s\"$$label must be at most $$maxLength characters\"` template -- a refactor changing the message format would silently break UIs surfacing this text to users; got: ${overCapBody("error").str}")
          }
        }
      }
    }
  }

  // Pin the documented profile-field CONTROL-CHARACTER
  // REJECTION contract at PlatformUserAuth.scala lines
  // 1149-1150's sanitizeOptionalField control-char check
  // (`if value.exists(ch => ch.toInt < 0x20 || ch.toInt ==
  // 0x7F) then throw new IllegalArgumentException(s"$label
  // must not contain control characters")`) -- the
  // CONTROL-CHAR-REJECTION pin verifies the documented
  // defense where any INTERNAL C0 control character (code <
  // 0x20: NUL, TAB, LF, CR, ESC, etc.) OR DEL (0x7F) in a
  // profile field is rejected with a 400, while internal
  // SPACES (0x20) + printable chars (0x21-0x7E) are allowed
  // (so legal names like "John Smith" pass). SIXTIETH
  // per-emission-site SHAPE pin overall; the boundary nuance
  // is that the line 1139 `.map(_.trim)` strips
  // leading/trailing whitespace+controls FIRST (Scala's
  // String.trim removes ch <= 0x20), so the control-char
  // check at lines 1149-1150 specifically catches INTERNAL
  // controls that survive the trim; the CONTROL-CHAR-REJECTION
  // contract is OPERATIONALLY CRITICAL because (per the
  // documented inline comment at lines 1142-1148): (a) a
  // newline / NUL / ESC in a stored profile field has no
  // legitimate use and would CORRUPT audit-log fields when
  // the value eventually surfaces (the audit log is
  // line-oriented; an embedded newline would split one log
  // record into two, breaking grep-based operator workflows +
  // potentially forging fake log lines), (b) embedded
  // controls CONFUSE JSON consumers + trip line-oriented
  // dashboards downstream, (c) an embedded ESC could inject
  // terminal escape sequences that execute when an operator
  // cats the stored value in a terminal (the classic
  // log-injection-to-terminal-escape attack); per-format
  // regression vectors uniquely caught (NOT caught by the
  // 24b07ac max-length boundary pin which targets the LENGTH
  // dimension): (i) refactor dropping the lines 1149-1150
  // control-char check would silently allow newlines/NULs/ESC
  // into stored profile fields, reopening the
  // audit-log-corruption + terminal-escape-injection vectors,
  // (ii) refactor changing the boundary from `< 0x20` to `<=
  // 0x20` would silently reject internal SPACES, breaking
  // legal multi-word names like "John Smith" (the documented
  // allowed case), (iii) refactor dropping the `== 0x7F` DEL
  // check would silently allow the DEL char (which terminals
  // interpret as backspace, enabling visual spoofing of the
  // stored value), (iv) refactor changing the error-message
  // format would break UIs surfacing the text; test approach:
  // register a user, then verify (POSITIVE) an internal space
  // is allowed, (NEGATIVE) each of the 4 fields rejects a
  // representative internal control char with the documented
  // message, and (BOUNDARY) the 0x1F/0x20/0x7E/0x7F sweep
  // confirms the exact `< 0x20 || == 0x7F` predicate. NOTE:
  // bodies are built via ujson.write so the control char is
  // PROPERLY JSON-ESCAPED on the wire (a raw control byte
  // would be invalid JSON + rejected by the parser at a
  // DIFFERENT layer -- we want the char to reach the
  // sanitizeOptionalField check, so it must arrive as a valid
  // parsed string with an embedded control char).
  test("profile-field CONTROL-CHARACTER REJECTION contract: internal C0 controls (< 0x20) + DEL (0x7F) are rejected with the documented `<label> must not contain control characters` 400, while internal spaces (0x20) + printables are allowed per PlatformUserAuth.scala lines 1149-1150's sanitizeOptionalField control-char check") {
    withStaticSite { staticDir =>
      withUserStorePath { storePath =>
        withServer(staticDir, platformAuth = Some(PlatformUserAuth.Config(storePath = storePath))) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          val registerResp = postJson(
            s"$baseUri/api/auth/register",
            """{"email":"ctrl-char@example.com","password":"correct-horse-battery","displayName":"X"}"""
          )
          assertEquals(registerResp.statusCode(), 201,
            clue = "register MUST 201 to drive the control-char rejection test")
          val csrfToken = jsonBody(registerResp)("csrfToken").str
          val sessionCookieValue = sessionCookie(registerResp)

          // Build the body via ujson.write so the value is
          // PROPERLY JSON-ESCAPED on the wire (the control char
          // arrives as a valid parsed string, reaching the
          // sanitizeOptionalField check rather than failing at
          // the JSON-parse layer).
          def postField(jsonKey: String, value: String): HttpResponse[String] =
            val body = ujson.write(ujson.Obj(jsonKey -> ujson.Str(value)))
            httpClient.send(
              HttpRequest.newBuilder()
                .uri(URI.create(s"$baseUri/api/auth/profile"))
                .method("POST", HttpRequest.BodyPublishers.ofString(body))
                .header("Content-Type", "application/json")
                .header("Cookie", sessionCookieValue)
                .header("X-CSRF-Token", csrfToken)
                .build(),
              HttpResponse.BodyHandlers.ofString()
            )

          // (1) POSITIVE: internal space is ALLOWED -- the
          // documented "John Smith" case (0x20 is NOT < 0x20,
          // so it passes the control-char predicate)
          val spaceResp = postField("displayName", "John Smith")
          assertEquals(spaceResp.statusCode(), 200,
            clue = s"displayName with an internal SPACE (`John Smith`) MUST be accepted (200) -- spaces (0x20) are NOT control chars per the `< 0x20` predicate; a refactor changing the boundary to `<= 0x20` would silently reject legal multi-word names; got: ${spaceResp.statusCode()}, body: ${spaceResp.body()}")
          assertEquals(ujson.read(spaceResp.body())("user").obj("displayName").str, "John Smith",
            clue = "displayName `John Smith` MUST round-trip intact (the internal space is preserved)")

          // (2) NEGATIVE: per-field internal-control-char
          // rejection. Each field gets a DISTINCT representative
          // control char to spread coverage: displayName=LF,
          // heroName=NUL, preferredSite=ESC, timeZone=DEL. The
          // control char is INTERNAL (surrounded by printables)
          // so it survives the line 1139 `.trim`.
          val controlCases = Vector(
            ("displayName", "displayName", 0x0a, "LF (0x0A)"),
            ("heroName", "heroName", 0x00, "NUL (0x00)"),
            ("preferredSite", "preferredSite", 0x1b, "ESC (0x1B)"),
            ("timeZone", "timeZone", 0x7f, "DEL (0x7F)")
          )
          controlCases.foreach { case (jsonKey, label, codepoint, charName) =>
            val value = "Aa" + codepoint.toChar.toString + "Bb"
            val resp = postField(jsonKey, value)
            assertEquals(resp.statusCode(), 400,
              clue = s"$jsonKey with an internal $charName MUST be rejected (400) per PlatformUserAuth.scala lines 1149-1150's control-char check -> AuthStack.scala line 235's `400 -> error` mapping; a refactor dropping the check would silently allow control chars that corrupt audit logs + inject terminal escapes; got: ${resp.statusCode()}, body: ${resp.body()}")
            val body = jsonBody(resp)
            assertEquals(body.obj.keys.toSet, Set("error"),
              clue = s"$jsonKey control-char 400 MUST emit the universal 1-field {error} shape per AuthStack.scala line 561's Left-fold; got: ${body.obj.keys.toVector.sorted.mkString(", ")}")
            val expectedMessage = s"$label must not contain control characters"
            assertEquals(body("error").str, expectedMessage,
              clue = s"$jsonKey control-char 400 error message MUST be EXACTLY `$expectedMessage` per PlatformUserAuth.scala line 1150's template; got: ${body("error").str}")
          }

          // (3) BOUNDARY SWEEP on displayName confirming the
          // exact `< 0x20 || == 0x7F` predicate at the 4 edge
          // codepoints: 0x1F (US, just below space) REJECTED,
          // 0x20 (space) ALLOWED, 0x7E (~, just below DEL)
          // ALLOWED, 0x7F (DEL) REJECTED.
          val boundarySweep = Vector(
            (0x1f, true, "0x1F (US, just below space)"),
            (0x20, false, "0x20 (space)"),
            (0x7e, false, "0x7E (~, just below DEL)"),
            (0x7f, true, "0x7F (DEL)")
          )
          boundarySweep.foreach { case (codepoint, shouldReject, charDesc) =>
            // Internal placement so the char survives .trim
            val value = "Aa" + codepoint.toChar.toString + "Bb"
            val resp = postField("displayName", value)
            if shouldReject then
              assertEquals(resp.statusCode(), 400,
                clue = s"displayName with internal $charDesc MUST be REJECTED (400) per the `< 0x20 || == 0x7F` predicate; got: ${resp.statusCode()}")
              assertEquals(jsonBody(resp)("error").str, "displayName must not contain control characters",
                clue = s"$charDesc rejection MUST carry the documented control-char message")
            else
              assertEquals(resp.statusCode(), 200,
                clue = s"displayName with internal $charDesc MUST be ACCEPTED (200) -- it is NOT < 0x20 and NOT == 0x7F per the documented predicate; a refactor widening the boundary would silently reject this legal printable; got: ${resp.statusCode()}, body: ${resp.body()}")
          }
        }
      }
    }
  }

  // Pin the documented profile-field WHITESPACE-TRIM contract
  // at PlatformUserAuth.scala line 1139's sanitizeOptionalField
  // `raw.map(_.trim).filter(_.nonEmpty)` chain -- the
  // WHITESPACE-TRIM pin verifies the documented THIRD behavior
  // of sanitizeOptionalField (complementing the max-length
  // check at 1140-1141 + the control-char check at 1149-1150):
  // (a) leading/trailing whitespace (any char <= 0x20 per
  // Scala's String.trim, including SPACE + TAB + CR + LF) is
  // TRIMMED off before storage, and (b) a value that is
  // whitespace-ONLY trims to empty + is filtered out -> the
  // Option becomes None -> the field is treated as omitted
  // (which CLEARS heroName/preferredSite/timeZone per the
  // 81324be asymmetry, but PRESERVES displayName via the line
  // 669 getOrElse fallback). SIXTY-FIRST per-emission-site
  // SHAPE pin overall; the parse-layer optionalString
  // (HandHistoryReviewServerApi.scala lines 708-716) does NOT
  // trim/nullify whitespace (it returns Some("   ") for a
  // whitespace-only value), so the trim+filter behavior
  // genuinely ORIGINATES at line 1139 -- this pin targets that
  // emission site; the WHITESPACE-TRIM contract is
  // OPERATIONALLY CRITICAL because: (a) trimming surrounding
  // whitespace is the documented normalization that prevents
  // visually-identical-but-byte-different stored values (e.g.
  // "Hero" vs " Hero " would otherwise be distinct stored
  // strings, confusing operator searches + breaking
  // deduplication), (b) the whitespace-only -> None ->
  // clear/preserve semantic is what lets a frontend form
  // submit an empty/spaces-only field to CLEAR it (for
  // heroName/preferredSite/timeZone) without a dedicated
  // clear endpoint -- a refactor dropping the .filter
  // (_.nonEmpty) would silently STORE the empty string instead
  // of clearing, breaking the documented clear-by-empty
  // contract, (c) the COMPLEMENTARY relationship with the
  // control-char check is subtle + documented: leading/
  // trailing TABS (0x09 <= 0x20) are TRIMMED AWAY (allowed,
  // silently removed) while INTERNAL tabs are REJECTED as
  // control chars -- because the .trim at line 1139 runs
  // BEFORE the control-char check at 1149, so edge tabs are
  // gone before the check sees them; per-format regression
  // vectors uniquely caught (NOT caught by the 24b07ac
  // max-length OR c38ad49 control-char pins): (i) refactor
  // dropping the `.map(_.trim)` would silently store
  // surrounding whitespace AND change leading/trailing tabs
  // from TRIMMED to REJECTED (the control-char check would
  // then see them), (ii) refactor dropping the `.filter
  // (_.nonEmpty)` would silently store empty strings instead
  // of clearing the field, breaking the clear-by-empty
  // contract, (iii) refactor reordering trim AFTER the
  // control-char check would silently reject leading/trailing
  // tabs/newlines that should be trimmed; test approach:
  // register a user, then verify (1) leading/trailing SPACES
  // trimmed, (2) leading/trailing TABS trimmed (NOT rejected
  // as control -- the complementary-to-control-char signal),
  // (3) whitespace-only heroName -> CLEARED (None), (4)
  // whitespace-only displayName -> PRESERVED (the trim+
  // asymmetry interaction), (5) internal space PRESERVED
  // (trim only affects edges).
  test("profile-field WHITESPACE-TRIM contract: leading/trailing whitespace (spaces + tabs) is trimmed before storage, whitespace-only values become None (clearing heroName but preserving displayName via the asymmetry), and internal spaces are preserved per PlatformUserAuth.scala line 1139's `raw.map(_.trim).filter(_.nonEmpty)` chain -- completes the sanitizeOptionalField trifecta with the 24b07ac max-length + c38ad49 control-char pins") {
    withStaticSite { staticDir =>
      withUserStorePath { storePath =>
        withServer(staticDir, platformAuth = Some(PlatformUserAuth.Config(storePath = storePath))) { server =>
          val baseUri = s"http://${server.binding.host}:${server.binding.port}"

          val registerResp = postJson(
            s"$baseUri/api/auth/register",
            """{"email":"trim@example.com","password":"correct-horse-battery","displayName":"X"}"""
          )
          assertEquals(registerResp.statusCode(), 201,
            clue = "register MUST 201 to drive the whitespace-trim test")
          val csrfToken = jsonBody(registerResp)("csrfToken").str
          val sessionCookieValue = sessionCookie(registerResp)

          // Build the body via ujson.write so tabs/whitespace
          // are PROPERLY JSON-ESCAPED on the wire + arrive as a
          // valid parsed string reaching sanitizeOptionalField.
          def postObj(obj: ujson.Obj): HttpResponse[String] =
            httpClient.send(
              HttpRequest.newBuilder()
                .uri(URI.create(s"$baseUri/api/auth/profile"))
                .method("POST", HttpRequest.BodyPublishers.ofString(ujson.write(obj)))
                .header("Content-Type", "application/json")
                .header("Cookie", sessionCookieValue)
                .header("X-CSRF-Token", csrfToken)
                .build(),
              HttpResponse.BodyHandlers.ofString()
            )

          // (1) Leading/trailing SPACES trimmed: " Hero " ->
          // "Hero" stored
          val spaceResp = postObj(ujson.Obj("heroName" -> ujson.Str(" Hero ")))
          assertEquals(spaceResp.statusCode(), 200,
            clue = s"heroName with surrounding spaces MUST be accepted (200) -- the trim removes them; got: ${spaceResp.statusCode()}, body: ${spaceResp.body()}")
          assertEquals(ujson.read(spaceResp.body())("user").obj("heroName").str, "Hero",
            clue = s"heroName ` Hero ` MUST be TRIMMED to `Hero` per line 1139's `.map(_.trim)` -- a refactor dropping the trim would silently store the surrounding whitespace, producing visually-identical-but-byte-different stored values; got: ${ujson.read(spaceResp.body())("user").obj("heroName").str}")

          // (2) Leading/trailing TABS trimmed (NOT rejected as
          // control). The tab (0x09 <= 0x20) is removed by trim
          // BEFORE the control-char check at line 1149 sees it
          // -- the documented complementary-to-control-char
          // behavior (internal tabs WOULD be rejected, but edge
          // tabs are trimmed away).
          val tabResp = postObj(ujson.Obj("heroName" -> ujson.Str("\tHero\t")))
          assertEquals(tabResp.statusCode(), 200,
            clue = s"heroName with surrounding TABS MUST be accepted (200) -- the line 1139 `.trim` removes edge tabs (0x09 <= 0x20) BEFORE the line 1149 control-char check, so they are silently trimmed NOT rejected; a refactor reordering trim AFTER the control-char check would silently reject this legal value; got: ${tabResp.statusCode()}, body: ${tabResp.body()}")
          assertEquals(ujson.read(tabResp.body())("user").obj("heroName").str, "Hero",
            clue = s"heroName `\\tHero\\t` MUST be TRIMMED to `Hero` (edge tabs removed); got: ${ujson.read(tabResp.body())("user").obj("heroName").str}")

          // (3) WHITESPACE-ONLY heroName -> CLEARED (None). The
          // value trims to empty + is filtered out -> None ->
          // heroName cleared (per the 81324be asymmetry where
          // None clears heroName).
          // First set heroName to a real value.
          postObj(ujson.Obj("heroName" -> ujson.Str("SetHero")))
          val clearResp = postObj(ujson.Obj("heroName" -> ujson.Str("   ")))
          assertEquals(clearResp.statusCode(), 200,
            clue = s"whitespace-only heroName MUST be accepted (200) -- it trims to empty + filters to None; got: ${clearResp.statusCode()}")
          assertEquals(ujson.read(clearResp.body())("user").obj.get("heroName"), Some(ujson.Null),
            clue = s"whitespace-only heroName MUST CLEAR the field (null) per line 1139's `.filter(_.nonEmpty)` -> None -> the 81324be asymmetry clears heroName; a refactor dropping the .filter would silently store the empty string instead of clearing, breaking the documented clear-by-empty contract; got: ${ujson.read(clearResp.body())("user").obj.get("heroName")}")

          // (4) WHITESPACE-ONLY displayName -> PRESERVED (the
          // trim + asymmetry interaction). The value trims to
          // empty + filters to None -> sanitizeDisplayName
          // returns None -> line 669's getOrElse(current)
          // PRESERVES the previous displayName.
          postObj(ujson.Obj("displayName" -> ujson.Str("KeepMe")))
          val preserveResp = postObj(ujson.Obj("displayName" -> ujson.Str("   ")))
          assertEquals(preserveResp.statusCode(), 200,
            clue = s"whitespace-only displayName MUST be accepted (200); got: ${preserveResp.statusCode()}")
          assertEquals(ujson.read(preserveResp.body())("user").obj("displayName").str, "KeepMe",
            clue = s"whitespace-only displayName MUST PRESERVE the previous value `KeepMe` per the trim+asymmetry interaction (trims to empty -> None -> line 669 getOrElse(current.displayName)) -- this is the documented difference from heroName (which CLEARS): displayName treats None as preserve, heroName treats None as clear; got: ${ujson.read(preserveResp.body())("user").obj("displayName").str}")

          // (5) Internal space PRESERVED (trim only affects
          // edges, not internal whitespace)
          val internalResp = postObj(ujson.Obj("displayName" -> ujson.Str("John Smith")))
          assertEquals(internalResp.statusCode(), 200,
            clue = s"displayName `John Smith` (internal space) MUST be accepted (200); got: ${internalResp.statusCode()}")
          assertEquals(ujson.read(internalResp.body())("user").obj("displayName").str, "John Smith",
            clue = s"displayName `John Smith` MUST preserve the INTERNAL space (trim only removes leading/trailing whitespace, not internal); got: ${ujson.read(internalResp.body())("user").obj("displayName").str}")
        }
      }
    }
  }

  // Pin the documented Location-header-on-202 contract for BOTH
  // submission endpoints. Deploy doc line 66 explicitly says
  // "Submissions return `202 Accepted` with `Location` and
  // `Retry-After` headers plus a JSON body containing `jobId`,
  // `status` (always the literal string "queued" on a fresh `202` --
  // the worker hasn't started yet; the GET poll endpoint surfaces
  // later state transitions), `statusUrl`, `submittedAtEpochMs`,
  // `pollAfterMs`." The Location header carries the same value as
  // the body's statusUrl field; that equality is the contract a
  // generic HTTP-202-aware client (e.g. Postman's "follow Location"
  // toggle, a generic REST library's auto-follow) relies on -- it
  // reads Location from the response header rather than parsing the
  // body, AND its poll loop expects the URL it gets back to be the
  // canonical status URL the body would have surfaced. A refactor
  // that dropped the Location header (or emitted a different value
  // than statusUrl) would silently break those generic clients
  // without affecting our own bundled frontend (which keys on
  // body.statusUrl, not the header). HandHistoryReviewServerApi.scala
  // emits the Location header at lines 110 (/api/analyze-hand-history)
  // and 156 (/api/playing-hall), in both cases with value
  // `accepted.statusUrl` -- so the contract is symmetric across both
  // submission endpoints. Existing Retry-After test (line ~3775) was
  // adjacent but specifically asserted Retry-After, not Location;
  // before this commit Location was entirely untested at the 202
  // response level. New test covers both endpoints in one test
  // body since the contract is identical across them and a
  // refactor would likely touch either both or just one (the
  // either-both-or-only-one shape parallels the body-cap triplet
  // [4e4b385 / 034b14c / e2045b9] and the CSRF quintuplet
  // [a550186 / 26bf0d7 / eef3779 / e6e0961] -- per-endpoint pins
  // catch the asymmetric-drift case).
  test("submission 202 responses carry a Location header equal to the body's statusUrl on both /api/analyze-hand-history and /api/playing-hall") {
    withStaticSite { staticDir =>
      val backend = new BlockingBackend(Right(sampleAnalysisResult))
      val playingHallBackend = new BlockingPlayingHallBackend(Right(samplePlayingHallResult))
      withServer(staticDir, backend = backend, playingHallBackend = playingHallBackend) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        // /api/analyze-hand-history submission: 202 with Location =
        // body.statusUrl (the relative status-poll URL, NOT a fully
        // qualified URI -- the server emits relative URLs so a
        // reverse proxy doesn't need to rewrite them).
        val analyzeResp = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
        assertEquals(analyzeResp.statusCode(), 202,
          clue = "analyze submission must return 202 Accepted -- the documented submit-success shape per deploy doc line 66")
        val analyzeStatusUrl = jsonBody(analyzeResp)("statusUrl").str
        val analyzeLocation = headerValue(analyzeResp, "Location").getOrElse(
          fail("analyze 202 response MUST emit a Location header per deploy doc line 66 -- generic HTTP-202-aware clients (e.g. Postman 'follow Location' toggle, REST libraries with auto-follow) rely on this header to find the status URL without parsing the body; missing Location silently breaks those clients while leaving our bundled frontend (which keys on body.statusUrl) unaffected"))
        assertEquals(analyzeLocation, analyzeStatusUrl,
          clue = s"analyze Location header must equal body.statusUrl -- both are documented to point at the same poll URL, and a divergence (e.g. body has the relative path but header has a fully qualified URI from a misconfigured proxy) would confuse generic clients that key on one OR the other; got header=$analyzeLocation, body=$analyzeStatusUrl")
        // Drain the backend so the next submission isn't queue-blocked.
        backend.release.countDown()

        // /api/playing-hall submission: same contract, same shape.
        val hallResp = postJson(s"$baseUri/api/playing-hall", validPlayingHallPayload)
        assertEquals(hallResp.statusCode(), 202,
          clue = "hall submission must return 202 Accepted -- same submit-success shape as analyze, symmetric across both endpoints")
        val hallStatusUrl = jsonBody(hallResp)("statusUrl").str
        val hallLocation = headerValue(hallResp, "Location").getOrElse(
          fail("hall 202 response MUST emit a Location header per deploy doc line 66 -- same generic-client contract as analyze; HandHistoryReviewServerApi.scala emits the header at line 156 with value accepted.statusUrl"))
        assertEquals(hallLocation, hallStatusUrl,
          clue = s"hall Location header must equal body.statusUrl -- symmetric with analyze; got header=$hallLocation, body=$hallStatusUrl")
        // Drain the hall backend on the way out.
        playingHallBackend.release.countDown()
      }
    }
  }

  test("analysis submission returns a job id, keeps the server responsive, and completes via polling") {
    withStaticSite { staticDir =>
      val backend = new BlockingBackend(Right(sampleAnalysisResult))
      withServer(staticDir, backend = backend) { server =>
        val baseUri = s"http://${server.binding.host}:${server.binding.port}"

        val submissionResponse = postJson(s"$baseUri/api/analyze-hand-history", validUploadPayload)
        assertEquals(submissionResponse.statusCode(), 202)
        assertEquals(headerValue(submissionResponse, "Retry-After"), Some("1"))
        val submission = jsonBody(submissionResponse)
        assertEquals(submission("status").str, "queued")
        val statusUri = s"$baseUri${submission("statusUrl").str}"

        assert(backend.started.await(3, TimeUnit.SECONDS), "analysis backend never started")

        val runningResponse = get(statusUri)
        assertEquals(headerValue(runningResponse, "Retry-After"), Some("1"))
        val running = jsonBody(runningResponse)
        assertEquals(running("status").str, "running")
        val health = getJson(s"$baseUri/api/health")
        assertEquals(health("runningJobs").num.toInt, 1)
        assertEquals(health("queuedJobs").num.toInt, 0)
        assertEquals(get(s"$baseUri/").statusCode(), 200)

        backend.release.countDown()

        val completed = awaitTerminalJob(statusUri)
        assertEquals(completed("status").str, "completed")
        assertEquals(completed("result")("site").str, "PokerStars")
        assertEquals(completed("result")("handsImported").num.toInt, 1)
        assertEquals(completed("result")("handsAnalyzed").num.toInt, 1)
        assertEquals(completed("result")("trace")("request")("normalizedHeroName").str, "Hero")
        assertEquals(completed("result")("trace")("import")("handsImported").num.toInt, 1)
        assertEquals(completed("result")("trace")("hands")(0)("status").str, "analyzed")
        assertEquals(completed("result")("trace")("summary")("decisionsAnalyzed").num.toInt, 1)
      }
    }
  }

