      val error = result.left.toOption.getOrElse("")
      assert(error.contains("ALLOW_UNAUTHENTICATED_PUBLIC_BIND"))
      assert(error.contains("BASIC_AUTH_*/USER_STORE_PATH"))
    }
  }

